insert into _kbsplit(node_id, blocks, search_text) values
(46, $kbsplit$[{"t":"list","id":"a1-1-2-2-b1","imp":"core","items":["1、==微电子技术基础元件的演变==：电子管阶段产生了广播、电视、无线电通信、仪器仪表、自动化技术和第一代电子计算机。晶体管于1948年发明，加上印制电路组装技术的使用，使电子电路在小型化方面前进了一大步，产生了第二代计算机。集成电路（Integrated Circuit，简称IC）于20世纪50年代出现，以半导体单晶片作为材料；现代集成电路使用的半导体材料通常是硅（Si），也可以是砷化镓（GaAs）等化合物半导体。小规模集成电路使电子电路进一步缩小，产生了第三代计算机；超大规模集成电路使电子电路微型化，产生了第四代计算机。目前所使用的计算机都属于第四代计算机。","2、==集成电路按所含电子元件数目分类==：^^按所包含的电子元件数目分^^：","1）中小规模集成电路，集成对象为门电路或单级放大器；","2）大规模集成电路，集成对象为功能部件、子系统；","3）PC机使用的微处理器、芯片组、图形加速芯片都是超大规模（VLSI）和极大规模集成电路。","3、==集成电路按用途分类==：按用途分为==通用集成电路和专用集成电路（ASIC==，Application Specific Integrated Circuit）。专用集成电路是指应特定用户要求和特定电子系统的需要而设计、制造的集成电路。目前用CPLD（复杂可编程逻辑器件）和FPGA（现场可编程逻辑阵列）进行ASIC设计是最为流行的方式之一，它们的共性是都具有用户现场可编程特性，都支持边界扫描技术，但两者在集成度、速度以及编程方式上各有特点。","4、^^集成电路按功能分类^^：按功能分为^^数字集成电路和模拟集成电路^^。数字集成电路如逻辑电路、存储器、微处理器、微控制器、数字信号处理器等；模拟集成电路又称为线性电路，如信号放大器、功率放大器等。","5、==按晶体管结构、电路和工艺分类==：双极型电路、金属氧化物半导体（MOS）电路、双极-金属化物半导体集成电路等","6、^^四、集成电路的发展趋势^^：集成度的提高规律（Moore定律）：单块集成电路的集成度平均每18～24个月翻一番（目前符合）。集成电路的出路：量子计算机、光子计算机、生物（酶）计算机。","7、==IC 卡，即集成电路卡，它是把集成电路芯片密封在塑料卡基片内，使其成为能存储信息、处理和传递数据的载体。==","8、^^IC 卡特点：存储信息量大、保密性能强、可以防止伪造和窃用、抗干扰能力强、可靠性高^^","9、==IC 卡的类型（按芯片分类）==：","（1）==存储器卡==","①、原理：封装的集成电路以存储器为主，信息可长期保存，也可通过读卡器改写。","②、特点：有写保护和加密电路，可以对存储卡进行加密操作。","③、适用场景：^^校园卡、公交卡、医保卡、消费卡、门禁卡等^^。","（2）==CPU 卡==：","①、原理：封装的集成电路为中央处理器（CPU）、数据存储器、程序处理器，以及带有芯片操作系统。","②、特点： 处理能力强，保密性能更好","③、适用场景：^^银行卡、信用卡、证件、手机SIM 卡^^等","10、==IC 卡的类型（按使用方式分类）==","（1）==接触式IC 卡（如电话卡）==","①、工作原理：使用时必须将IC 卡插入读卡机，通过金属触点传输数据","②、特点：易磨损、怕脏、寿命短等","③、适用场景：信息量大、读写操作复杂场合","（2）==非接触式IC 卡（即射频卡、感应卡；如身份证）==","①、原理：采用电磁感应方式无线传输数据，无源（卡中无电源）和免接触","②、特点：操作方便，快捷，采用全密封胶固化，防水、防污，使用寿命长","③、适用场景：用于读写信息较简单的场合，如身份验证等","（3）==双界面卡（如公交一卡通、银行IC 卡）==","①、原理：可通过接触方式的触点，也可相隔一定距离以射频方式使用的IC 卡","②、特点：一卡多用、一卡通用、高度安全、快速交易等","③、适用场景：适用于恶劣工作环境和自助消费场所，适用于对安全性要求高的系统，可作为金融电子钱包应用。","11、==五、IC卡应用（所有IC卡都可以加密）==","1. ^^按芯片分^^：==CPU卡==，卡中既有硬件也有操作系统，安全级别高（信用卡、SIM卡、身份证）；存储器卡，用于安全级别不高的场合（饭卡、公交卡）。","12、==身份鉴别==：^^又名真实性鉴别、身份认证。 定义^^：证实某人或某物（消息、文件、主机等）的真实身份与其所声称的身份是否相符的过程。 目的：防止欺诈和假冒攻击。 认证方式：IC卡、磁卡、USB钥匙、口令、眼底虹膜等。 在计算机系统中，单纯采用令牌（如IC卡、磁卡等）进行身份认证的缺点是：丢失令牌将导致他人能轻易进行假冒，从而带来安全隐患。"],"title":"","ordered":false},{"t":"callout","id":"a1-1-2-2-b2","imp":"core","kind":"tip","text":"集成电路按集成度分为：==小规模（SSI，<100 个元器件）、中规模（MSI）、大规模（LSI）、超大规模（VLSI）与甚大规模（ULSI）==；IC 卡按芯片类型分为==存储器卡（只含 EEPROM）与 CPU 卡（含微处理器与操作系统，安全性极高）==；按接口分为接触式与非接触式（RFID/NFC）。","title":"考向复习提示：集成电路规模划分与 IC 卡分类"},{"t":"callout","id":"a1-1-2-2-b3","imp":"core","kind":"trap","text":"==磁卡（通过磁条记录信息）极易被消磁与复制，安全性低==；而 ==IC 卡（内嵌半导体芯片）防磁、防潮、存储容量大且支持硬件级加密认证==；专转本常考单选：第三代居民身份证和现代银行芯片卡均属于==非接触式 CPU 卡==，切勿误选为磁卡或普通存储卡。","title":"高频易错陷阱：磁卡与 IC 卡的安全性辨析"}]$kbsplit$::jsonb, $kbsplitse$A1-1.2.2 集成电路发展与分类，IC 卡。 1、微电子技术基础元件的演变：电子管阶段产生了广播、电视、无线电通信、仪器仪表、自动化技术和第一代电子计算机。晶体管于1948年发明，加上印制电路组装技术的使用，使电子电路在小型化方面前进了一大步，产生了第二代计算机。集成电路（Integrated Circuit，简称IC）于20世纪50年代出现，以半导体单晶片作为材料；现代集成电路使用的半导体材料通常是硅（Si），也可以是砷化镓（GaAs）等化合物半导体。小规模集成电路使电子电路进一步缩小，产生了第三代计算机；超大规模集成电路使电子电路微型化，产生了第四代计算机。目前所使用的计算机都属于第四代计算机。 2、集成电路按所含电子元件数目分类：按所包含的电子元件数目分： 1）中小规模集成电路，集成对象为门电路或单级放大器； 2）大规模集成电路，集成对象为功能部件、子系统； 3）PC机使用的微处理器、芯片组、图形加速芯片都是超大规模（VLSI）和极大规模集成电路。 3、集成电路按用途分类：按用途分为通用集成电路和专用集成电路（ASIC，Application Specific Integrated Circuit）。专用集成电路是指应特定用户要求和特定电子系统的需要而设计、制造的集成电路。目前用CPLD（复杂可编程逻辑器件）和FPGA（现场可编程逻辑阵列）进行ASIC设计是最为流行的方式之一，它们的共性是都具有用户现场可编程特性，都支持边界扫描技术，但两者在集成度、速度以及编程方式上各有特点。 4、集成电路按功能分类：按功能分为数字集成电路和模拟集成电路。数字集成电路如逻辑电路、存储器、微处理器、微控制器、数字信号处理器等；模拟集成电路又称为线性电路，如信号放大器、功率放大器等。 5、按晶体管结构、电路和工艺分类：双极型电路、金属氧化物半导体（MOS）电路、双极-金属化物半导体集成电路等 6、四、集成电路的发展趋势：集成度的提高规律（Moore定律）：单块集成电路的集成度平均每18～24个月翻一番（目前符合）。集成电路的出路：量子计算机、光子计算机、生物（酶）计算机。 7、IC 卡，即集成电路卡，它是把集成电路芯片密封在塑料卡基片内，使其成为能存储信息、处理和传递数据的载体。 8、IC 卡特点：存储信息量大、保密性能强、可以防止伪造和窃用、抗干扰能力强、可靠性高 9、IC 卡的类型（按芯片分类）： （1）存储器卡 ①、原理：封装的集成电路以存储器为主，信息可长期保存，也可通过读卡器改写。 ②、特点：有写保护和加密电路，可以对存储卡进行加密操作。 ③、适用场景：校园卡、公交卡、医保卡、消费卡、门禁卡等。 （2）CPU 卡： ①、原理：封装的集成电路为中央处理器（CPU）、数据存储器、程序处理器，以及带有芯片操作系统。 ②、特点： 处理能力强，保密性能更好 ③、适用场景：银行卡、信用卡、证件、手机SIM 卡等 10、IC 卡的类型（按使用方式分类） （1）接触式IC 卡（如电话卡） ①、工作原理：使用时必须将IC 卡插入读卡机，通过金属触点传输数据 ②、特点：易磨损、怕脏、寿命短等 ③、适用场景：信息量大、读写操作复杂场合 （2）非接触式IC 卡（即射频卡、感应卡；如身份证） ①、原理：采用电磁感应方式无线传输数据，无源（卡中无电源）和免接触 ②、特点：操作方便，快捷，采用全密封胶固化，防水、防污，使用寿命长 ③、适用场景：用于读写信息较简单的场合，如身份验证等 （3）双界面卡（如公交一卡通、银行IC 卡） ①、原理：可通过接触方式的触点，也可相隔一定距离以射频方式使用的IC 卡 ②、特点：一卡多用、一卡通用、高度安全、快速交易等 ③、适用场景：适用于恶劣工作环境和自助消费场所，适用于对安全性要求高的系统，可作为金融电子钱包应用。 11、五、IC卡应用（所有IC卡都可以加密） 1. 按芯片分：CPU卡，卡中既有硬件也有操作系统，安全级别高（信用卡、SIM卡、身份证）；存储器卡，用于安全级别不高的场合（饭卡、公交卡）。 12、身份鉴别：又名真实性鉴别、身份认证。 定义：证实某人或某物（消息、文件、主机等）的真实身份与其所声称的身份是否相符的过程。 目的：防止欺诈和假冒攻击。 认证方式：IC卡、磁卡、USB钥匙、口令、眼底虹膜等。 在计算机系统中，单纯采用令牌（如IC卡、磁卡等）进行身份认证的缺点是：丢失令牌将导致他人能轻易进行假冒，从而带来安全隐患。 考向复习提示：集成电路规模划分与 IC 卡分类 集成电路按集成度分为：小规模（SSI，<100 个元器件）、中规模（MSI）、大规模（LSI）、超大规模（VLSI）与甚大规模（ULSI）；IC 卡按芯片类型分为存储器卡（只含 EEPROM）与 CPU 卡（含微处理器与操作系统，安全性极高）；按接口分为接触式与非接触式（RFID/NFC）。 高频易错陷阱：磁卡与 IC 卡的安全性辨析 磁卡（通过磁条记录信息）极易被消磁与复制，安全性低；而 IC 卡（内嵌半导体芯片）防磁、防潮、存储容量大且支持硬件级加密认证；专转本常考单选：第三代居民身份证和现代银行芯片卡均属于非接触式 CPU 卡，切勿误选为磁卡或普通存储卡。$kbsplitse$),(53, $kbsplit$[{"t":"list","id":"a1-1-4-1-b1","imp":"core","items":["1、==键盘、鼠标、笔输入设备、扫描仪、数字摄像头概述==","^^1）键盘^^：==用于操作计算机设备运行的指令和数据输入装置==，也指经过系统安排操作一台机器或设备的一组功能键（如打字机、电脑键盘）。","^^2）鼠标^^：==计算机的一种外接输入设备，也是计算机显示系统纵横坐标定位的指示器。==","^^3）笔输入设备^^：==主要有手写板、手写笔。==","^^4）扫描仪^^：==一种捕获影像的装置，作为光机电一体化的电脑外设产品，可将影像转换为计算机可以显示、编辑、存储和输出的数字格式。==","^^5）数字摄像头^^：==可以将视频采集设备产生的模拟视频信号转换成数字信号，进而将其储存在计算机里。==","2、==外部设备包括输入设备和输出设备==：外部设备包括==输入设备和输出设备==。扫描仪是输入设备，常见的输入设备还有鼠标、键盘、手写板等。","3、==扫描仪的主要性能指标==：","^^1）光学分辨率（dpi）^^：==反映图像大小==，分辨率越高，扫描后的图像越大、越清晰，例如1200×2400 dpi；扫描仪的分辨率决定了扫描仪的档次和价格。","^^2）色彩位数（色彩深度）^^：==反映色彩逼真度==，色彩位数越多，图像越真实，例如32 bit。","^^3）扫描幅面^^：==指被扫描原稿的最大尺寸==，例如A3、A4等。","^^4）与主机的接口类型^^：==SCSI、USB、IEEE 1394接口==。","4、==汉字输入编码与内码==：==用不同的输入编码方法输入同一个汉字==，其内码是一样的。联机手写汉字识别使用笔输入设备；印刷体汉字识别输入使用扫描仪和OCR。","5、==键盘与鼠标==：==计算机必备的输入设备是键盘==，鼠标是最常用的输入设备。","6、==扫描仪的分类==：手持式扫描仪、平板式扫描仪（家用和办公自动化领域广泛应用）、胶片专用扫描仪和滚筒式扫描仪（专业印刷排版领域）。"],"title":"","ordered":false},{"t":"callout","id":"a1-1-4-1-b2","imp":"core","kind":"tip","text":"常见输入设备：键盘、鼠标、触摸屏、手写板、图形数字化仪、扫描仪、摄像头；扫描仪核心指标是==光学分辨率（DPI，每英寸点数）与色彩深度（如 24 位/48 位真彩色）==；鼠标主要性能参数包括==分辨率（DPI）与刷新率==。","title":"考向复习提示：常用输入设备分类及技术指标"},{"t":"callout","id":"a1-1-4-1-b3","imp":"core","kind":"trap","text":"键盘上敲击一个按键向主机发送的是硬件==扫描码（与按键物理位置相关）==，而不是字符的 ASCII 码；操作系统键盘驱动程序负责将扫描码根据当前的 Shift/CapsLock 状态转换为对应的 ASCII 码或汉字机内码；专转本常考单选：按下键和松开键会分别产生通码和断码。","title":"高频易错陷阱：扫描码与 ASCII 码的区别"}]$kbsplit$::jsonb, $kbsplitse$A1-1.4.1 键盘，鼠标，笔输入设备，扫描仪，数字摄像头概述。 1、键盘、鼠标、笔输入设备、扫描仪、数字摄像头概述 1）键盘：用于操作计算机设备运行的指令和数据输入装置，也指经过系统安排操作一台机器或设备的一组功能键（如打字机、电脑键盘）。 2）鼠标：计算机的一种外接输入设备，也是计算机显示系统纵横坐标定位的指示器。 3）笔输入设备：主要有手写板、手写笔。 4）扫描仪：一种捕获影像的装置，作为光机电一体化的电脑外设产品，可将影像转换为计算机可以显示、编辑、存储和输出的数字格式。 5）数字摄像头：可以将视频采集设备产生的模拟视频信号转换成数字信号，进而将其储存在计算机里。 2、外部设备包括输入设备和输出设备：外部设备包括输入设备和输出设备。扫描仪是输入设备，常见的输入设备还有鼠标、键盘、手写板等。 3、扫描仪的主要性能指标： 1）光学分辨率（dpi）：反映图像大小，分辨率越高，扫描后的图像越大、越清晰，例如1200×2400 dpi；扫描仪的分辨率决定了扫描仪的档次和价格。 2）色彩位数（色彩深度）：反映色彩逼真度，色彩位数越多，图像越真实，例如32 bit。 3）扫描幅面：指被扫描原稿的最大尺寸，例如A3、A4等。 4）与主机的接口类型：SCSI、USB、IEEE 1394接口。 4、汉字输入编码与内码：用不同的输入编码方法输入同一个汉字，其内码是一样的。联机手写汉字识别使用笔输入设备；印刷体汉字识别输入使用扫描仪和OCR。 5、键盘与鼠标：计算机必备的输入设备是键盘，鼠标是最常用的输入设备。 6、扫描仪的分类：手持式扫描仪、平板式扫描仪（家用和办公自动化领域广泛应用）、胶片专用扫描仪和滚筒式扫描仪（专业印刷排版领域）。 考向复习提示：常用输入设备分类及技术指标 常见输入设备：键盘、鼠标、触摸屏、手写板、图形数字化仪、扫描仪、摄像头；扫描仪核心指标是光学分辨率（DPI，每英寸点数）与色彩深度（如 24 位/48 位真彩色）；鼠标主要性能参数包括分辨率（DPI）与刷新率。 高频易错陷阱：扫描码与 ASCII 码的区别 键盘上敲击一个按键向主机发送的是硬件扫描码（与按键物理位置相关），而不是字符的 ASCII 码；操作系统键盘驱动程序负责将扫描码根据当前的 Shift/CapsLock 状态转换为对应的 ASCII 码或汉字机内码；专转本常考单选：按下键和松开键会分别产生通码和断码。$kbsplitse$),(59, $kbsplit$[{"t":"list","id":"a1-1-6-1-b1","imp":"core","items":["1、==外存储器，简称外存，也称辅存。一般有硬盘、光盘、软盘、U 盘等。==","2、==硬盘==","^^（1）非易失性存储器，可以长期保存二进制信息^^","^^（2）存储原理：通过磁头对盘片（铝合金或玻璃）上磁性材料粒子的不同磁化方向来记录数据。^^","^^（3）硬盘物理结构：磁盘的磁道和扇区^^","①、==磁道==：@@盘面上有几千个磁道，由里向外有一圈一圈的同心圆，每个同心圆就是一个磁道。相同磁道的存储数据量相同，相同磁道的存储密度不相同。每个磁道都有一个编号，最外面的是0 磁道（由外往里递增）@@","②、==扇区==：^^每个磁道被划分为若干段（段又叫扇区），每个扇区的存储容量为512 字节。^^","（4）@@硬盘存储容量=磁头数*柱面数*扇区数（每个磁道上）*每扇区字节数（正常就是512B）@@","（5）==硬盘的主要性能指标：容量、平均等待时间、平均存取时间、数据传输速率等==","①、==容量==：GB 为单位，目前已经出现TB 级的硬盘","②、==平均等待时间==@@=最大等待时间和最小等待时间的平均=磁盘旋转一圈时间的一半@@。","以7200 转硬盘为例，磁盘旋转一圈的时间为60s/7200=0.00833s=8.33ms最好的情况，数据恰好在磁头下，这是最小等待时间T1=0最坏的情况，数据恰好在盘片对面，这是最大等待时间 T1=8.33ms由于硬盘是匀速转动的，所以平均等待时间是最大等待时间和最小等待时间的平均=(0+8.33)/2=4.165ms即平均等待时间=60s/7200/2=4.165ms","③、==平均存取时间==^^（几ms~几十ms 之间）=寻道时间+旋转等待时间+数据传输时间；由硬盘的旋转速度、磁头寻道时间和数据传输速率所决定^^","④、==数据传输速率==^^：外部传输速率（主机向硬盘缓存读写）、内部传输速率（盘片上读写）；内部传输速率小于外部传输速率。^^","（6）==与主机的接口==：并行ATA（现在很少用），==IDE、串行SATA(目前主流)==","（7）使用事项：==断电插拔硬盘（防止读写过程中关电）、环境控制（防尘、防高温、防潮湿等）、即时清理硬盘(文件、目录、碎片等)、防计算机病毒等。==","（8）==分类：机械硬盘、固态硬盘(SSD)、移动硬盘(USB3.0/3.1 接口)=="],"title":"","ordered":false},{"h":431,"t":"img","w":1289,"id":"a1-1-6-1-b2","imp":"normal","src":"/kb-assets/theory/p22_r0_ed19d1a002c481b6.png","title":""},{"t":"list","id":"a1-1-6-1-b3","imp":"core","items":["==（9）机械硬盘和固态硬盘的主要区别：固态硬盘的存取速度要比机械硬盘的快。==","2、==光盘和光盘驱动器==","（1）^^光盘存储原理：光盘上有由里向外的连续螺旋形的光道，这一条光道是用于记录数据的，通过盘面上压制凹坑的方法来记录信息。凹坑边缘表示“1”，凹坑平坦部分表示”0”。^^","（2）光盘分类：==CD（红外光，650MB）盘片==、==DVD（红光,>=4.7GB）盘片==、==BD（蓝光，>=25GB）盘片==","^^①、CD 盘片：CD-ROM（只读）、CD-R(一次性可写)、CD-RW（可擦写）^^","^^②、DVD 盘片：只读盘片（DVD）、一次性可写盘片（DVD-R, DVD+R）、可擦写盘片（DVD-RW,DVD+RW DVD-RAM ）^^","^^③、蓝光盘片：BD(只读)、BD-R（一次性可写）、BD-RE（可擦写）^^","（3）光盘驱动器：只读光驱、可写光驱（光盘刻录机）","3、==U 盘（闪速存储器）==","（1）==属于半导体集成电路存储器，非易失性存储器==","（2）==U 盘：采用NAND Flash 存储器==","（3）容量：几个GB 至几百个GB","（4）接口：USB,即插即用，热插拔","（5）可以使用U 盘制启动操作系统","（6）U 盘也是一个8 位的嵌入式计算机","4、^^软盘^^","^^（1）以前使用最早的可移介质^^","^^（2）软盘的读写是通过软件盘驱动器来完成的。现在很多电脑上都没有软盘驱动器，甚至是光盘驱动器也没有。^^","^^（3）软盘的写保护是通过软件上左下小孔状态决定（闭合）^^","^^（4）软盘容量：磁道数x 扇区数x 盘面数x 每扇区存区数^^","^^（5）以3.5 的磁盘片为例，其容量的计算如下：^^","^^80(磁道)x18(扇区)x512bytes(扇区的大小)x2(双面)=1440x1024bytes=1440KB=1.44MB^^","5、==半导体芯片与内存、外存的关系==：==内存由半导体芯片构成==，但半导体芯片不都是内存，半导体芯片也可以是外存（如 U 盘）。内存按地址访问，外存可按文件名访问。","6、==光盘存储器要点==：^^特点^^：==成本不高、容量较大、可靠性好、不容易损坏==；盘面有指纹、灰尘时数据仍然可以读出；表面介质不受温度和环境的影响；但读出速度和数据传输速度比硬盘慢得多。 三代产品：第1代，1982年，CD光盘存储器，红外光，650MB；第2代，1995年，DVD光盘存储器，红光，4.7GB；第3代，2006年，BD光盘存储器，蓝光，25GB（单层）。 记录原理与磁盘不同，通过在盘面压制凹坑的方法记录信息：凹坑的边缘处表示“1”，凹坑内和凹坑外的平坦处表示“0”，信息的读出需使用激光进行分辨和识别。","7、==各类外存储器的原理、组成、分类与接口==：","^^1）软盘 原理^^：==软盘的读写通过软盘驱动器完成==。马达带动盘片转动，转速约为每分钟300转；磁头定位器是一个很小的步进马达，负责把磁头移动到正确的磁道，由磁头完成读写操作。 组成：软盘外壳和盘片。 分类：常用的有5.25英寸和3.5英寸两种。 接口：内置使用FDD接口，外置使用USB接口。","^^2）U盘 原理^^：==计算机把二进制数字信号转为复合二进制数字信号（加入分配、核对、堆栈等指令）==，读写到USB芯片适配接口，通过芯片处理信号，分配给EEPROM存储芯片的相应地址存储二进制数据，实现数据存储。 组成：主要由外壳和机芯组成。 分类：无驱型、加密型、启动型。","8、==CD光盘存储器系列==：^^组成^^：==CD光盘片、CD光盘驱动器（光盘刻录机）==。驱动器接口有SCSI接口、IDE接口、并行口和USB接口；驱动器分CD-ROM光驱和CD-RW刻录机，盘片分CD-ROM、CD-R和CD-RW三种。","① ==CD光盘片（Compact Disc==，小型光盘） CD-ROM光盘片：只读光盘，不能删除也不能写入，只能读出盘中的信息，存储容量为650MB、700MB。 CD-R光盘片：只写一次式光盘，只能写一次，写后不能删除和修改，只能读出。","9、==硬盘接口的演进与 I/O 并行==：==硬盘的接口已经从 IDE 发展到 SATA 接口==。 为了提高系统的效率，I/O 操作与 CPU 的数据处理操作通常是并行进行的。","10、==采用NAND型闪存芯片的产品==：^^U盘^^：==又称优盘、闪存盘==。机芯是一小块印刷电路板，机芯上的控制芯片是一个以8位CPU为核心的嵌入式计算机。支持即插即用，采用硬件加软件的双重数据安全防护。U盘可以模拟光盘和硬盘启动操作系统（需重新设置CMOS）。 存储卡：是在闪存芯片基础上做成的固态存储卡。"],"title":"","ordered":false},{"t":"callout","id":"a1-1-6-1-b4","imp":"core","kind":"tip","text":"外存主要类型：机械硬盘 HDD（磁表面记录）、固态硬盘 SSD（Flash 闪存介质）、光盘（光介质，CD/DVD/BD蓝光）、磁带（顺序存取大容量归档）；SSD 相比 HDD 的绝对优势：==读写速度极快、无机械寻道寻道延迟、抗震抗跌落、工作静音零噪音、发热量低==。","title":"考向复习提示：常见外存储器介质及接口分类"},{"t":"callout","id":"a1-1-6-1-b5","imp":"core","kind":"trap","text":"固态硬盘内部基于闪存颗粒（SLC > MLC > TLC > QLC），Flash 颗粒的物理特性是==“按页（Page）读取和写入，但必须按块（Block）整块擦除”==；由于存在擦写循环次数（P/E）限制，SSD 必须依靠主控的==磨损均衡（Wear Leveling）算法==防止局部颗粒提前损坏；常考判断题考查写入前必须擦除的特性。","title":"高频易错陷阱：固态硬盘 SSD 读写寿命与擦除机制"}]$kbsplit$::jsonb, $kbsplitse$A1-1.6.1 常用几类外存储器的工作原理，组成，分类情况，接口类型。 1、外存储器，简称外存，也称辅存。一般有硬盘、光盘、软盘、U 盘等。 2、硬盘 （1）非易失性存储器，可以长期保存二进制信息 （2）存储原理：通过磁头对盘片（铝合金或玻璃）上磁性材料粒子的不同磁化方向来记录数据。 （3）硬盘物理结构：磁盘的磁道和扇区 ①、磁道：盘面上有几千个磁道，由里向外有一圈一圈的同心圆，每个同心圆就是一个磁道。相同磁道的存储数据量相同，相同磁道的存储密度不相同。每个磁道都有一个编号，最外面的是0 磁道（由外往里递增） ②、扇区：每个磁道被划分为若干段（段又叫扇区），每个扇区的存储容量为512 字节。 （4）硬盘存储容量=磁头数*柱面数*扇区数（每个磁道上）*每扇区字节数（正常就是512B） （5）硬盘的主要性能指标：容量、平均等待时间、平均存取时间、数据传输速率等 ①、容量：GB 为单位，目前已经出现TB 级的硬盘 ②、平均等待时间=最大等待时间和最小等待时间的平均=磁盘旋转一圈时间的一半。 以7200 转硬盘为例，磁盘旋转一圈的时间为60s/7200=0.00833s=8.33ms最好的情况，数据恰好在磁头下，这是最小等待时间T1=0最坏的情况，数据恰好在盘片对面，这是最大等待时间 T1=8.33ms由于硬盘是匀速转动的，所以平均等待时间是最大等待时间和最小等待时间的平均=(0+8.33)/2=4.165ms即平均等待时间=60s/7200/2=4.165ms ③、平均存取时间（几ms~几十ms 之间）=寻道时间+旋转等待时间+数据传输时间；由硬盘的旋转速度、磁头寻道时间和数据传输速率所决定 ④、数据传输速率：外部传输速率（主机向硬盘缓存读写）、内部传输速率（盘片上读写）；内部传输速率小于外部传输速率。 （6）与主机的接口：并行ATA（现在很少用），IDE、串行SATA(目前主流) （7）使用事项：断电插拔硬盘（防止读写过程中关电）、环境控制（防尘、防高温、防潮湿等）、即时清理硬盘(文件、目录、碎片等)、防计算机病毒等。 （8）分类：机械硬盘、固态硬盘(SSD)、移动硬盘(USB3.0/3.1 接口) （9）机械硬盘和固态硬盘的主要区别：固态硬盘的存取速度要比机械硬盘的快。 2、光盘和光盘驱动器 （1）光盘存储原理：光盘上有由里向外的连续螺旋形的光道，这一条光道是用于记录数据的，通过盘面上压制凹坑的方法来记录信息。凹坑边缘表示“1”，凹坑平坦部分表示”0”。 （2）光盘分类：CD（红外光，650MB）盘片、DVD（红光,>=4.7GB）盘片、BD（蓝光，>=25GB）盘片 ①、CD 盘片：CD-ROM（只读）、CD-R(一次性可写)、CD-RW（可擦写） ②、DVD 盘片：只读盘片（DVD）、一次性可写盘片（DVD-R, DVD+R）、可擦写盘片（DVD-RW,DVD+RW DVD-RAM ） ③、蓝光盘片：BD(只读)、BD-R（一次性可写）、BD-RE（可擦写） （3）光盘驱动器：只读光驱、可写光驱（光盘刻录机） 3、U 盘（闪速存储器） （1）属于半导体集成电路存储器，非易失性存储器 （2）U 盘：采用NAND Flash 存储器 （3）容量：几个GB 至几百个GB （4）接口：USB,即插即用，热插拔 （5）可以使用U 盘制启动操作系统 （6）U 盘也是一个8 位的嵌入式计算机 4、软盘 （1）以前使用最早的可移介质 （2）软盘的读写是通过软件盘驱动器来完成的。现在很多电脑上都没有软盘驱动器，甚至是光盘驱动器也没有。 （3）软盘的写保护是通过软件上左下小孔状态决定（闭合） （4）软盘容量：磁道数x 扇区数x 盘面数x 每扇区存区数 （5）以3.5 的磁盘片为例，其容量的计算如下： 80(磁道)x18(扇区)x512bytes(扇区的大小)x2(双面)=1440x1024bytes=1440KB=1.44MB 5、半导体芯片与内存、外存的关系：内存由半导体芯片构成，但半导体芯片不都是内存，半导体芯片也可以是外存（如 U 盘）。内存按地址访问，外存可按文件名访问。 6、光盘存储器要点：特点：成本不高、容量较大、可靠性好、不容易损坏；盘面有指纹、灰尘时数据仍然可以读出；表面介质不受温度和环境的影响；但读出速度和数据传输速度比硬盘慢得多。 三代产品：第1代，1982年，CD光盘存储器，红外光，650MB；第2代，1995年，DVD光盘存储器，红光，4.7GB；第3代，2006年，BD光盘存储器，蓝光，25GB（单层）。 记录原理与磁盘不同，通过在盘面压制凹坑的方法记录信息：凹坑的边缘处表示“1”，凹坑内和凹坑外的平坦处表示“0”，信息的读出需使用激光进行分辨和识别。 7、各类外存储器的原理、组成、分类与接口： 1）软盘 原理：软盘的读写通过软盘驱动器完成。马达带动盘片转动，转速约为每分钟300转；磁头定位器是一个很小的步进马达，负责把磁头移动到正确的磁道，由磁头完成读写操作。 组成：软盘外壳和盘片。 分类：常用的有5.25英寸和3.5英寸两种。 接口：内置使用FDD接口，外置使用USB接口。 2）U盘 原理：计算机把二进制数字信号转为复合二进制数字信号（加入分配、核对、堆栈等指令），读写到USB芯片适配接口，通过芯片处理信号，分配给EEPROM存储芯片的相应地址存储二进制数据，实现数据存储。 组成：主要由外壳和机芯组成。 分类：无驱型、加密型、启动型。 8、CD光盘存储器系列：组成：CD光盘片、CD光盘驱动器（光盘刻录机）。驱动器接口有SCSI接口、IDE接口、并行口和USB接口；驱动器分CD-ROM光驱和CD-RW刻录机，盘片分CD-ROM、CD-R和CD-RW三种。 ① CD光盘片（Compact Disc，小型光盘） CD-ROM光盘片：只读光盘，不能删除也不能写入，只能读出盘中的信息，存储容量为650MB、700MB。 CD-R光盘片：只写一次式光盘，只能写一次，写后不能删除和修改，只能读出。 9、硬盘接口的演进与 I/O 并行：硬盘的接口已经从 IDE 发展到 SATA 接口。 为了提高系统的效率，I/O 操作与 CPU 的数据处理操作通常是并行进行的。 10、采用NAND型闪存芯片的产品：U盘：又称优盘、闪存盘。机芯是一小块印刷电路板，机芯上的控制芯片是一个以8位CPU为核心的嵌入式计算机。支持即插即用，采用硬件加软件的双重数据安全防护。U盘可以模拟光盘和硬盘启动操作系统（需重新设置CMOS）。 存储卡：是在闪存芯片基础上做成的固态存储卡。 考向复习提示：常见外存储器介质及接口分类 外存主要类型：机械硬盘 HDD（磁表面记录）、固态硬盘 SSD（Flash 闪存介质）、光盘（光介质，CD/DVD/BD蓝光）、磁带（顺序存取大容量归档）；SSD 相比 HDD 的绝对优势：读写速度极快、无机械寻道寻道延迟、抗震抗跌落、工作静音零噪音、发热量低。 高频易错陷阱：固态硬盘 SSD 读写寿命与擦除机制 固态硬盘内部基于闪存颗粒（SLC > MLC > TLC > QLC），Flash 颗粒的物理特性是“按页（Page）读取和写入，但必须按块（Block）整块擦除”；由于存在擦写循环次数（P/E）限制，SSD 必须依靠主控的磨损均衡（Wear Leveling）算法防止局部颗粒提前损坏；常考判断题考查写入前必须擦除的特性。$kbsplitse$),(69, $kbsplit$[{"t":"list","id":"a2-2-2-1-b1","imp":"core","items":["1、==操作系统是用户与硬件的接口==：==操作系统是用户和硬件的接口==，也可以说成操作系统是软件和硬件的接口。","2、==网络服务、网络软件与网络操作系统==：","1）网络服务分为==交互服务和传播服务两大类==。","2）网络软件（Network Software）是在计算机网络环境中，用于支持数据通信和各种网络活动的软件。连入计算机网络的系统，通常根据系统本身的特点、能力和服务对象，配置不同的网络应用系统，其目的是使本机用户共享网中其他系统的资源，或是把本机系统的功能和资源提供给网中其他用户使用。","3）网络操作系统（Network Operating System，简称 NOS）是管理计算机网络资源的系统软件，是网络用户与计算机网络之间的接口。","3、^^进程（任务）^^：“进程”（即“任务”）是指^^程序在某个数据集上的一次运行活动^^，是操作系统分配资源的基本单位。","4、^^Windows 的用户与任务特性^^：^^Windows 既有单用户版本也有多用户版本^^，都是多任务操作系统。","5、^^远程使用巨型机资源^^：^^通过互联网将用户的计算机远程挂到巨型机上^^，使用巨型机的硬件和软件资源。","6、^^将整个屏幕复制到剪贴板^^：==将整个屏幕复制到剪贴板==：^^按【PrtSc】键^^。"],"title":"","ordered":false},{"t":"callout","id":"a2-2-2-1-b2","imp":"core","kind":"tip","text":"操作系统（OS）是紧贴硬件的第一层系统软件，是计算机系统的核心与基石；它的核心作用体现在：==对内作为计算机系统全部软硬件资源的统一管理者与分配者，对外作为用户和硬件之间的友好接口==；常见操作系统包括 Windows、Linux、macOS、Android、iOS。","title":"考向复习提示：操作系统的地位与核心作用"},{"t":"callout","id":"a2-2-2-1-b3","imp":"core","kind":"trap","text":"一台没有任何软件的计算机称为“裸机”；==裸机上首先必须安装的软件只能是操作系统（OS）==，任何语言处理程序、DBMS 或办公软件都无法脱离操作系统直接运行在裸机硬件之上；题目常给出多种软件让考生排序第一安装项，答案必然是操作系统。","title":"高频易错陷阱：裸机安装软件的唯一合法顺序"}]$kbsplit$::jsonb, $kbsplitse$A2-2.2.1 操作系统的基本概念、作用。 1、操作系统是用户与硬件的接口：操作系统是用户和硬件的接口，也可以说成操作系统是软件和硬件的接口。 2、网络服务、网络软件与网络操作系统： 1）网络服务分为交互服务和传播服务两大类。 2）网络软件（Network Software）是在计算机网络环境中，用于支持数据通信和各种网络活动的软件。连入计算机网络的系统，通常根据系统本身的特点、能力和服务对象，配置不同的网络应用系统，其目的是使本机用户共享网中其他系统的资源，或是把本机系统的功能和资源提供给网中其他用户使用。 3）网络操作系统（Network Operating System，简称 NOS）是管理计算机网络资源的系统软件，是网络用户与计算机网络之间的接口。 3、进程（任务）：“进程”（即“任务”）是指程序在某个数据集上的一次运行活动，是操作系统分配资源的基本单位。 4、Windows 的用户与任务特性：Windows 既有单用户版本也有多用户版本，都是多任务操作系统。 5、远程使用巨型机资源：通过互联网将用户的计算机远程挂到巨型机上，使用巨型机的硬件和软件资源。 6、将整个屏幕复制到剪贴板：将整个屏幕复制到剪贴板：按【PrtSc】键。 考向复习提示：操作系统的地位与核心作用 操作系统（OS）是紧贴硬件的第一层系统软件，是计算机系统的核心与基石；它的核心作用体现在：对内作为计算机系统全部软硬件资源的统一管理者与分配者，对外作为用户和硬件之间的友好接口；常见操作系统包括 Windows、Linux、macOS、Android、iOS。 高频易错陷阱：裸机安装软件的唯一合法顺序 一台没有任何软件的计算机称为“裸机”；裸机上首先必须安装的软件只能是操作系统（OS），任何语言处理程序、DBMS 或办公软件都无法脱离操作系统直接运行在裸机硬件之上；题目常给出多种软件让考生排序第一安装项，答案必然是操作系统。$kbsplitse$),(74, $kbsplit$[{"t":"list","id":"a2-2-3-1-b1","imp":"core","items":["1、==程序设计语言：主要用于描述算法，也称算法语言；==","2、==程序设计语言分类：机器语言（低级语言，计算机可以直接识别执行）、汇编语言（低级语言）、高级语言（如C,C#等）==","3、==机器语言==","==（1）机器语言就是计算机的指令系统，指令是使用二进制编码表示的。==","==（2）机器语言使用二进制代码编写，可以被计算机==@@直接识别并执行@@==，不需要翻译==","==（3）机器语言编写的程序记不住、难理解、编程效率低、不易维护，但是执行效率高==","==（4）机器语言对机器（硬件）有依赖性，移值性比较差。==","==（5）现在已经==@@不直接@@==用机器语言编写程序==","（6）举例：在MIPS 计算机上求最大公约数（GCD)的机器程序（16 进制表示）"],"title":"","ordered":false},{"h":256,"t":"img","w":1350,"id":"a2-2-3-1-b2","imp":"normal","src":"/kb-assets/theory/p33_r0_bc42df3ce9a6d5c6.png","title":""},{"t":"list","id":"a2-2-3-1-b3","imp":"core","items":["3、==汇编语言==","==（1）汇编语言是用助记符来表示机器指令中的操作符号与操作数。==","==（2）汇编语言是面向机器的程序设计语言（对机器仍有依赖性），属于低级语言==","==（3）汇编语言程序操作数直接使用十进制表示，程序相对容易理解==","（4）举例："],"title":"","ordered":false},{"h":301,"t":"img","w":956,"id":"a2-2-3-1-b4","imp":"normal","src":"/kb-assets/theory/p34_r0_9a62a18d2a73123d.png","title":""},{"t":"list","id":"a2-2-3-1-b5","imp":"core","items":["4、==高级语言==","==（1）高级语言（按近自然语言）容易理解、记忆和使用，降低了编程难度。==","==（2）高级语言克服汇编语言的缺陷，提高编程和维护效率==","==（3）高级语言程序移值性好，对硬件不太依赖==","==（4）高级语言对使用的符号、词汇、语法和语义等各种语言成分都有严格的规定==","（5）举例：C 语言举例","5、==程序设计语言的处理系统（翻译系统）==：==源程序经翻译程序转换为目标程序==。","1）汇编语言：汇编语言源程序经汇编程序（汇编器）翻译为机器语言目标程序。","2）高级语言：（笔译）源程序经编译程序（编译器）翻译为机器语言目标程序，可供多次执行； （口译）源程序经解释程序（解释器）边翻译边执行，不产生目标程序。 编译过程：编辑—编译—连接—运行。","6、==语言处理与算法基础==：^^机器语言^^：==二进制编写==，对硬件依赖强，不易移植，可以直接被计算机执行，运行速度最快，不易记忆和理解。 汇编语言：用助记符代替操作码和操作数，需汇编程序翻译，具有机器语言移植性差的缺点。 高级语言：算法语言，易记忆和理解，通用性、可移植性强，便于维护，运行速度慢。 高级语言基本成分：数据成分（数据类型和数据结构）、运算成分（算术运算和逻辑运算）、控制成分（顺序、条件和循环）、传输成分（输入和输出）。 系统开发：正文编辑—翻译—连接编辑—装入—执行。 汇编程序：把汇编语言翻译成机器语言。","7、==SQL 查询与排序==：^^查询学生表中男生的记录^^：SELECT 学号, 姓名, 性别 FROM 学生 WHERE 性别 '男' 按学号降序输出： SELECT 学号, 姓名, 性别 FROM 学生 ORDER BY 学号 DESC","8、^^计算机语言的发展与分类^^：==计算机语言的发展阶段==：^^机器语言：由 0 和 1 组成的指令^^。 汇编语言：用英文字母和数字表示指令。 高级语言：接近于人的自然语言和数学语言，分为面向过程的语言（非结构化的语言、结构化语言）和面向对象的语言。","9、^^文件管理与程序设计语言^^：^^文件管理强调的是对外存的管理^^，例如 Windows 对外存的文件采用树状的目录管理方式，也就是文件夹的管理方式。","四、程序设计语言 程序设计语言就是人类和计算机交流的语言。计算机只认识二进制，所以只能识别二进制语言，也就是机器语言。BIOS 芯片里面存放的就是机器语言。高级语言程序和汇编语言程序都需要翻译成机器语言程序才能被计算机执行。","10、^^软件发展的三个阶段^^：==第一阶段==：^^机器语言和汇编语言阶段^^。 第二阶段：高级语言（如 FORTRAN）阶段，操作系统出现，软件危机随之产生。 第三阶段：软件工程阶段，以工程化方法高质量、高效率地开发软件。 软件危机的根源是软件开发方式难以适应硬件性能与需求规模的快速增长。"],"title":"","ordered":false},{"h":607,"t":"img","w":615,"id":"a2-2-3-1-b6","imp":"normal","src":"/kb-assets/theory/p34_r1_dd36c456721a71d4.png","title":""},{"t":"callout","id":"a2-2-3-1-b7","imp":"core","kind":"tip","text":"程序设计语言演进经历三阶段：==第一代机器语言（纯二进制代码，CPU 唯一能直接识别与执行的语言）==；==第二代汇编语言（使用助记符表示指令，需经汇编程序翻译为机器码）==；==第三代高级语言（面向过程如 C、面向对象如 Java/C++，语法接近自然语言和数学表达式）==。","title":"考向复习提示：程序设计语言三阶段发展脉络"},{"t":"callout","id":"a2-2-3-1-b8","imp":"core","kind":"trap","text":"专转本单选常考：==机器语言和汇编语言统称为“低级语言”（面向硬件机器的语言）==；很多考生因汇编语言有英文助记符误将其归入高级语言；记住：凡是依赖具体 CPU 寄存器和硬件指令架构的语言都是低级语言，只有与具体硬件指令集解耦的才是高级语言！","title":"高频易错陷阱：低级语言 vs 高级语言划分界线"}]$kbsplit$::jsonb, $kbsplitse$A2-2.3.1 程序设计语言的分类。 1、程序设计语言：主要用于描述算法，也称算法语言； 2、程序设计语言分类：机器语言（低级语言，计算机可以直接识别执行）、汇编语言（低级语言）、高级语言（如C,C#等） 3、机器语言 （1）机器语言就是计算机的指令系统，指令是使用二进制编码表示的。 （2）机器语言使用二进制代码编写，可以被计算机直接识别并执行，不需要翻译 （3）机器语言编写的程序记不住、难理解、编程效率低、不易维护，但是执行效率高 （4）机器语言对机器（硬件）有依赖性，移值性比较差。 （5）现在已经不直接用机器语言编写程序 （6）举例：在MIPS 计算机上求最大公约数（GCD)的机器程序（16 进制表示） 3、汇编语言 （1）汇编语言是用助记符来表示机器指令中的操作符号与操作数。 （2）汇编语言是面向机器的程序设计语言（对机器仍有依赖性），属于低级语言 （3）汇编语言程序操作数直接使用十进制表示，程序相对容易理解 （4）举例： 4、高级语言 （1）高级语言（按近自然语言）容易理解、记忆和使用，降低了编程难度。 （2）高级语言克服汇编语言的缺陷，提高编程和维护效率 （3）高级语言程序移值性好，对硬件不太依赖 （4）高级语言对使用的符号、词汇、语法和语义等各种语言成分都有严格的规定 （5）举例：C 语言举例 5、程序设计语言的处理系统（翻译系统）：源程序经翻译程序转换为目标程序。 1）汇编语言：汇编语言源程序经汇编程序（汇编器）翻译为机器语言目标程序。 2）高级语言：（笔译）源程序经编译程序（编译器）翻译为机器语言目标程序，可供多次执行； （口译）源程序经解释程序（解释器）边翻译边执行，不产生目标程序。 编译过程：编辑—编译—连接—运行。 6、语言处理与算法基础：机器语言：二进制编写，对硬件依赖强，不易移植，可以直接被计算机执行，运行速度最快，不易记忆和理解。 汇编语言：用助记符代替操作码和操作数，需汇编程序翻译，具有机器语言移植性差的缺点。 高级语言：算法语言，易记忆和理解，通用性、可移植性强，便于维护，运行速度慢。 高级语言基本成分：数据成分（数据类型和数据结构）、运算成分（算术运算和逻辑运算）、控制成分（顺序、条件和循环）、传输成分（输入和输出）。 系统开发：正文编辑—翻译—连接编辑—装入—执行。 汇编程序：把汇编语言翻译成机器语言。 7、SQL 查询与排序：查询学生表中男生的记录：SELECT 学号, 姓名, 性别 FROM 学生 WHERE 性别 '男' 按学号降序输出： SELECT 学号, 姓名, 性别 FROM 学生 ORDER BY 学号 DESC 8、计算机语言的发展与分类：计算机语言的发展阶段：机器语言：由 0 和 1 组成的指令。 汇编语言：用英文字母和数字表示指令。 高级语言：接近于人的自然语言和数学语言，分为面向过程的语言（非结构化的语言、结构化语言）和面向对象的语言。 9、文件管理与程序设计语言：文件管理强调的是对外存的管理，例如 Windows 对外存的文件采用树状的目录管理方式，也就是文件夹的管理方式。 四、程序设计语言 程序设计语言就是人类和计算机交流的语言。计算机只认识二进制，所以只能识别二进制语言，也就是机器语言。BIOS 芯片里面存放的就是机器语言。高级语言程序和汇编语言程序都需要翻译成机器语言程序才能被计算机执行。 10、软件发展的三个阶段：第一阶段：机器语言和汇编语言阶段。 第二阶段：高级语言（如 FORTRAN）阶段，操作系统出现，软件危机随之产生。 第三阶段：软件工程阶段，以工程化方法高质量、高效率地开发软件。 软件危机的根源是软件开发方式难以适应硬件性能与需求规模的快速增长。 考向复习提示：程序设计语言三阶段发展脉络 程序设计语言演进经历三阶段：第一代机器语言（纯二进制代码，CPU 唯一能直接识别与执行的语言）；第二代汇编语言（使用助记符表示指令，需经汇编程序翻译为机器码）；第三代高级语言（面向过程如 C、面向对象如 Java/C++，语法接近自然语言和数学表达式）。 高频易错陷阱：低级语言 vs 高级语言划分界线 专转本单选常考：机器语言和汇编语言统称为“低级语言”（面向硬件机器的语言）；很多考生因汇编语言有英文助记符误将其归入高级语言；记住：凡是依赖具体 CPU 寄存器和硬件指令架构的语言都是低级语言，只有与具体硬件指令集解耦的才是高级语言！$kbsplitse$),(81, $kbsplit$[{"t":"list","id":"a2-2-4-2-b1","imp":"core","items":["（5）研究数据结构一般包括三方面：==数据的逻辑结构、数据的存储结构，定义在逻辑结构和存储结构上的运算。==","1、==存储结构、栈与队列、树与图结构要点==：","^^一、存储结构 顺序存储^^：==元素存储在连续的空间中==。若元素大小为 1B，则从内存 0# 地址开始，元素的下标就是地址码；若元素大小为 L B，则第 i 个元素的地址为：元素首地址 + i×L。顺序存储不容易插入和删除。 链式存储：每个结点不仅有数据本身，还有体现数据之间关系的指针，结点由值域和指针域组成。单向链表中每个结点有一个指针，指向其后继结点；最后一个结点的指针域为空，头结点的值域为空，指针域为空表示单向链表的结束。链式存储很容易插入与删除。","==二、栈与队列==","1. ==栈：运算受限的线性表==，只能在栈顶插入与删除，原则是后进先出（LIFO）。","2、==数据结构的三要素与基本结论==：^^数据结构包括三方面内容^^：==数据的逻辑结构、数据的存储结构和定义在该结构上的运算==。 逻辑结构分为线性结构和非线性结构。线性结构包括一般线性表以及栈、队列、数组等特殊线性表；非线性结构包括集合、树形结构（一般树、二叉树）和图形结构（有向图、无向图）。 存储结构分为顺序存储和链式存储，任何一个逻辑结构在计算机中都可以采用这两种方式存储。 数据的运算包括查找、排序、插入、删除、修改等。 要点：栈的特点是先进后出；队列的特点是先进先出，在队尾插入元素、在队头删除元素，说“在队尾删除元素”是错误的。","3、==数据的物理结构（存储结构）==：数据的存储结构也称为数据的物理结构，是指==数据逻辑结构在计算机中的存放方式==，是面向计算机的，包括数据元素的存储方式和关系的存储方式。常见的存储结构有顺序、链式、索引、散列等。","① ^^顺序存储结构^^：==把逻辑上相邻的数据元素存储在物理位置也相邻的存储单元里==，通过存储单元的邻近关系体现数据元素之间的逻辑关系，主要应用于线性的数据结构。顺序存储结构只存储结点的数据，不存储结点之间的相互关系信息，一般称为紧凑存储结构。","② ^^链式存储结构^^：==各数据元素存储位置随意==，不要求逻辑上相邻的数据元素在物理位置上也相邻，结点间的逻辑关系用附加的指针域表示。","4、==数据结构的三方面内容与逻辑结构、存储结构==：","^^1) 数据结构包含三方面内容^^：","① ==逻辑结构（或抽象结构）==","② ==存储结构==","③ ==操作（或运算）==","==2) 什么是逻辑结构==？ 抽象地描述数据及数据之间的关系，包含四种：","① ^^集合结构（属于同一个集合。如^^：==一篮子鸡蛋==，关系是鸡蛋都属于同一个篮子）","② ==线性结构（反映线性关系==，紧跟它前面的只有一个，紧跟它后面的只有一个。如：银行窗口前的排队）","③ ^^树结构（层次关系。如^^：==家谱==。特点是除根结点外，其他结点的父结点是唯一的）","④ ==图或网状结构（任意关系）==","==3) 什么是存储结构==？ 逻辑结构在计算机存储器中（内存或外存）的实现。","5、==常用的数据结构与两种存储结构的比较==：^^常用的数据结构^^：","==1) 集合结构==","2) 线性结构（线性表是由若干同类型数据元素组成的有限序列，其中任意两个数据元素之间具有先后关系）","==3) 树形结构==","^^4) 网状结构 链接结构与顺序结构的比较^^：","- ^^易于扩充空间^^：==链接结构好==，顺序结构一般。","- ^^插入、删除运算^^：==链接结构好==，顺序结构一般。","- ^^是否占用连续存储空间^^：==链接结构否==，顺序结构是。","- ^^存储空间效率^^：==链接结构较好==，顺序结构好。","6、==数据结构的研究内容==：^^内容包括^^：","==1）数据的逻辑结构==：==用于抽象地反映数据元素之间的约束关系==，而不考虑其在计算机中的存储方式。","==2）数据的物理存储结构==：==数据的逻辑结构在计算机存储器上的实现==。","3）数据的运算。"],"title":"","ordered":false},{"t":"callout","id":"a2-2-4-2-b2","imp":"core","kind":"tip","text":"算法优劣的核心评价指标：==时间复杂度（算法执行耗费的时间随问题规模 n 增长的数量级，记作 O(f(n))）==与==空间复杂度（算法执行过程中所需的最大辅助存储空间量，记作 O(g(n))）==；两者通常相互权衡，不可替代。","title":"考向复习提示：算法复杂度度量体系（时间与空间）"},{"t":"callout","id":"a2-2-4-2-b3","imp":"core","kind":"trap","text":"专转本判断题必考陷阱：==算法的时间复杂度是指算法基本操作重复执行次数关于问题规模 n 的渐进趋势数量级，绝不是指程序在具体计算机上运行所耗费的绝对秒数！==绝对秒数与 CPU 主频、编译器优化和当前负载高度相关，不是算法理论度量指标！","title":"高频易错陷阱：时间复杂度绝非实际运行秒数"}]$kbsplit$::jsonb, $kbsplitse$A2-2.4.2 数据结构的定义，数据的逻辑结构与存储结构，数据结构的图形表示，线性结构与非线性结构的概念。 （5）研究数据结构一般包括三方面：数据的逻辑结构、数据的存储结构，定义在逻辑结构和存储结构上的运算。 1、存储结构、栈与队列、树与图结构要点： 一、存储结构 顺序存储：元素存储在连续的空间中。若元素大小为 1B，则从内存 0# 地址开始，元素的下标就是地址码；若元素大小为 L B，则第 i 个元素的地址为：元素首地址 + i×L。顺序存储不容易插入和删除。 链式存储：每个结点不仅有数据本身，还有体现数据之间关系的指针，结点由值域和指针域组成。单向链表中每个结点有一个指针，指向其后继结点；最后一个结点的指针域为空，头结点的值域为空，指针域为空表示单向链表的结束。链式存储很容易插入与删除。 二、栈与队列 1. 栈：运算受限的线性表，只能在栈顶插入与删除，原则是后进先出（LIFO）。 2、数据结构的三要素与基本结论：数据结构包括三方面内容：数据的逻辑结构、数据的存储结构和定义在该结构上的运算。 逻辑结构分为线性结构和非线性结构。线性结构包括一般线性表以及栈、队列、数组等特殊线性表；非线性结构包括集合、树形结构（一般树、二叉树）和图形结构（有向图、无向图）。 存储结构分为顺序存储和链式存储，任何一个逻辑结构在计算机中都可以采用这两种方式存储。 数据的运算包括查找、排序、插入、删除、修改等。 要点：栈的特点是先进后出；队列的特点是先进先出，在队尾插入元素、在队头删除元素，说“在队尾删除元素”是错误的。 3、数据的物理结构（存储结构）：数据的存储结构也称为数据的物理结构，是指数据逻辑结构在计算机中的存放方式，是面向计算机的，包括数据元素的存储方式和关系的存储方式。常见的存储结构有顺序、链式、索引、散列等。 ① 顺序存储结构：把逻辑上相邻的数据元素存储在物理位置也相邻的存储单元里，通过存储单元的邻近关系体现数据元素之间的逻辑关系，主要应用于线性的数据结构。顺序存储结构只存储结点的数据，不存储结点之间的相互关系信息，一般称为紧凑存储结构。 ② 链式存储结构：各数据元素存储位置随意，不要求逻辑上相邻的数据元素在物理位置上也相邻，结点间的逻辑关系用附加的指针域表示。 4、数据结构的三方面内容与逻辑结构、存储结构： 1) 数据结构包含三方面内容： ① 逻辑结构（或抽象结构） ② 存储结构 ③ 操作（或运算） 2) 什么是逻辑结构？ 抽象地描述数据及数据之间的关系，包含四种： ① 集合结构（属于同一个集合。如：一篮子鸡蛋，关系是鸡蛋都属于同一个篮子） ② 线性结构（反映线性关系，紧跟它前面的只有一个，紧跟它后面的只有一个。如：银行窗口前的排队） ③ 树结构（层次关系。如：家谱。特点是除根结点外，其他结点的父结点是唯一的） ④ 图或网状结构（任意关系） 3) 什么是存储结构？ 逻辑结构在计算机存储器中（内存或外存）的实现。 5、常用的数据结构与两种存储结构的比较：常用的数据结构： 1) 集合结构 2) 线性结构（线性表是由若干同类型数据元素组成的有限序列，其中任意两个数据元素之间具有先后关系） 3) 树形结构 4) 网状结构 链接结构与顺序结构的比较： - 易于扩充空间：链接结构好，顺序结构一般。 - 插入、删除运算：链接结构好，顺序结构一般。 - 是否占用连续存储空间：链接结构否，顺序结构是。 - 存储空间效率：链接结构较好，顺序结构好。 6、数据结构的研究内容：内容包括： 1）数据的逻辑结构：用于抽象地反映数据元素之间的约束关系，而不考虑其在计算机中的存储方式。 2）数据的物理存储结构：数据的逻辑结构在计算机存储器上的实现。 3）数据的运算。 考向复习提示：算法复杂度度量体系（时间与空间） 算法优劣的核心评价指标：时间复杂度（算法执行耗费的时间随问题规模 n 增长的数量级，记作 O(f(n))）与空间复杂度（算法执行过程中所需的最大辅助存储空间量，记作 O(g(n))）；两者通常相互权衡，不可替代。 高频易错陷阱：时间复杂度绝非实际运行秒数 专转本判断题必考陷阱：算法的时间复杂度是指算法基本操作重复执行次数关于问题规模 n 的渐进趋势数量级，绝不是指程序在具体计算机上运行所耗费的绝对秒数！绝对秒数与 CPU 主频、编译器优化和当前负载高度相关，不是算法理论度量指标！$kbsplitse$),(97, $kbsplit$[{"t":"list","id":"a3-3-2-2-b1","imp":"core","items":["1、常用的有线局域网：共享式以太网、交换式以太网、千兆/万兆以太网；","==（1）共享式以太网：==","==①、网络互联设备：以集线器（HUB）为中心，总线型结构。==","==②、传输介质：同轴电缆、双绞线、光纤等。==","==③、带宽方式：共享==","==④、通信方式：广播式通信==","==（2）交换以太网：==","==①、网络互联设备：以以太交换（Switch）为中心，星型结构==","==②、传输介质：双绞线、光纤等。==","==③、带宽方式：独享==","==④、通信方式：点到点通信==","==（3）千兆/万兆以太网==","==①、网络互联设备：借助不同速率交换机以树状（树形拓扑结构）将许多小型以太网连接起来,构成“校-院系-室、组“的多层次局域网（如企业网、校园网等）。==","==②、传输介质：光纤、双绞线等==","==③、万兆以太网包含多种类型，分别适用于局域网、城域网和广域网==","2、==MAC 地址的组成==：==每块以太网卡都有一个全球唯一的 MAC 地址==，MAC 地址由 6 个字节（48 位二进制）组成。","3、==传输速率与带宽==：==数据传输速率即数据率==，也称比特率，是计算机网络中最重要的性能指标，指数据链路中每秒传输的二进制位数目。速率的单位是b/s，或kb/s、Mb/s、Gb/s等： 1 kb/s＝103 b/s； 1 Mb/s＝106 b/s； 1 Gb/s＝109 b/s； 1 Tb/s＝1012 b/s。 例：假设数据传输速率为56 kb/s，传输一幅分辨率为640×480、6.5万种颜色的未压缩图像，所需时间为(640×480×16)/56000≈87.8秒。 在计算机网络中，“带宽”指数据链路所能达到的最高数据传输速率，有时也称为信道容量。","4、==Web 2.0 的含义==：==Web 2.0 又称第二代互联网==，是相对于 Web 1.0 的新的时代，指利用 Web 平台、由用户主导生成内容的互联网产品模式，以区别于传统由网站雇员主导生成内容的模式。它更注重交互性，是信息技术发展引发网络革命所带来的以人为本的创新模式在互联网领域的体现，也是由专业人员织网到所有用户参与织网的创新民主化进程。 Web 2.0 模式下的互联网应用具有去中心化、开放、共享等显著特点：","1）用户分享：不受时间和地域限制地分享各种观点，用户既能获取需要的信息，也能发布自己的观点。","2）信息聚合：信息在网络上不断积累，不会丢失。","5、==MAC 帧格式与网卡==：^^局域网中的数据传输^^：==采用分组交换技术==，把每台计算机要传输的数据分成帧，即 MAC 帧；一次只能传输 1 帧，不允许一次传任意多的数据；数据帧以时分多路复用方式共享传输介质。 MAC 帧的组成：有效载荷（真正传输的数据）、源计算机 MAC 地址、目的计算机 MAC 地址、控制信息、校验信息。校验信息用于确认接收的数据是否正确，若出错，源计算机将这一帧数据重发。","6、==以太网使用的传输介质==：^^同轴电缆^^：==早期使用==，速率 10 Mb/s 的以太网曾采用，价格较高。 双绞线（5 类线）：大量用于速率为 10 Mb/s 和 100 Mb/s 的以太网。 光纤：用于速率为千兆（1 Gb/s）和万兆（10 Gb/s）的以太网。 双绞线和 RJ-45 插头（水晶头）是目前以太网使用最多的传输介质。","7、==光纤分布式数字接口网（FDDI）==：FDDI 网络可以覆盖较大的范围，能支持较高的数据传输速率（100Mb/s），实用中常用于==构造局域网的主干部分==，把许多不同部门的局域网互相连接起来。由于 FDDI 的帧格式和其他常用局域网的帧格式不同，因此与其他局域网进行互连时，需要通过网关或路由器才能实现。"],"title":"","ordered":false},{"t":"callout","id":"a3-3-2-2-b2","imp":"normal","kind":"tip","text":"• 双绞线（Twisted Pair）：两根绝缘导线互绞抵消电磁干扰，分为无屏蔽 UTP（五类、超五类、六类）和屏蔽 STP； • 光纤（Optical Fiber）：利用光的全反射原理传输光脉冲，分为单模光纤（纤芯细、衰减少、传输距离极远适合骨干网）与多模光纤（纤芯粗、成本低适合短距）； • 无线介质：无线电波、微波、红外线。","title":"考向复习提示：有线与无线传输介质特性梳理"},{"t":"callout","id":"a3-3-2-2-b3","imp":"core","kind":"trap","text":"专转本必背数值：标准以太网中采用双绞线（UTP）通过 RJ-45 水晶头连接交换机时，==单段双绞线的最大无中继有效传输距离严格限定为 100 米==！超过 100 米信号衰减与畸变急剧恶化导致丢包，必须通过中继器或交换机重新放大整形！","title":"高频易错陷阱：双绞线单段最大有效传输距离"}]$kbsplit$::jsonb, $kbsplitse$A3-3.2.2 有线局域网。 1、常用的有线局域网：共享式以太网、交换式以太网、千兆/万兆以太网； （1）共享式以太网： ①、网络互联设备：以集线器（HUB）为中心，总线型结构。 ②、传输介质：同轴电缆、双绞线、光纤等。 ③、带宽方式：共享 ④、通信方式：广播式通信 （2）交换以太网： ①、网络互联设备：以以太交换（Switch）为中心，星型结构 ②、传输介质：双绞线、光纤等。 ③、带宽方式：独享 ④、通信方式：点到点通信 （3）千兆/万兆以太网 ①、网络互联设备：借助不同速率交换机以树状（树形拓扑结构）将许多小型以太网连接起来,构成“校-院系-室、组“的多层次局域网（如企业网、校园网等）。 ②、传输介质：光纤、双绞线等 ③、万兆以太网包含多种类型，分别适用于局域网、城域网和广域网 2、MAC 地址的组成：每块以太网卡都有一个全球唯一的 MAC 地址，MAC 地址由 6 个字节（48 位二进制）组成。 3、传输速率与带宽：数据传输速率即数据率，也称比特率，是计算机网络中最重要的性能指标，指数据链路中每秒传输的二进制位数目。速率的单位是b/s，或kb/s、Mb/s、Gb/s等： 1 kb/s＝103 b/s； 1 Mb/s＝106 b/s； 1 Gb/s＝109 b/s； 1 Tb/s＝1012 b/s。 例：假设数据传输速率为56 kb/s，传输一幅分辨率为640×480、6.5万种颜色的未压缩图像，所需时间为(640×480×16)/56000≈87.8秒。 在计算机网络中，“带宽”指数据链路所能达到的最高数据传输速率，有时也称为信道容量。 4、Web 2.0 的含义：Web 2.0 又称第二代互联网，是相对于 Web 1.0 的新的时代，指利用 Web 平台、由用户主导生成内容的互联网产品模式，以区别于传统由网站雇员主导生成内容的模式。它更注重交互性，是信息技术发展引发网络革命所带来的以人为本的创新模式在互联网领域的体现，也是由专业人员织网到所有用户参与织网的创新民主化进程。 Web 2.0 模式下的互联网应用具有去中心化、开放、共享等显著特点： 1）用户分享：不受时间和地域限制地分享各种观点，用户既能获取需要的信息，也能发布自己的观点。 2）信息聚合：信息在网络上不断积累，不会丢失。 5、MAC 帧格式与网卡：局域网中的数据传输：采用分组交换技术，把每台计算机要传输的数据分成帧，即 MAC 帧；一次只能传输 1 帧，不允许一次传任意多的数据；数据帧以时分多路复用方式共享传输介质。 MAC 帧的组成：有效载荷（真正传输的数据）、源计算机 MAC 地址、目的计算机 MAC 地址、控制信息、校验信息。校验信息用于确认接收的数据是否正确，若出错，源计算机将这一帧数据重发。 6、以太网使用的传输介质：同轴电缆：早期使用，速率 10 Mb/s 的以太网曾采用，价格较高。 双绞线（5 类线）：大量用于速率为 10 Mb/s 和 100 Mb/s 的以太网。 光纤：用于速率为千兆（1 Gb/s）和万兆（10 Gb/s）的以太网。 双绞线和 RJ-45 插头（水晶头）是目前以太网使用最多的传输介质。 7、光纤分布式数字接口网（FDDI）：FDDI 网络可以覆盖较大的范围，能支持较高的数据传输速率（100Mb/s），实用中常用于构造局域网的主干部分，把许多不同部门的局域网互相连接起来。由于 FDDI 的帧格式和其他常用局域网的帧格式不同，因此与其他局域网进行互连时，需要通过网关或路由器才能实现。 考向复习提示：有线与无线传输介质特性梳理 • 双绞线（Twisted Pair）：两根绝缘导线互绞抵消电磁干扰，分为无屏蔽 UTP（五类、超五类、六类）和屏蔽 STP； • 光纤（Optical Fiber）：利用光的全反射原理传输光脉冲，分为单模光纤（纤芯细、衰减少、传输距离极远适合骨干网）与多模光纤（纤芯粗、成本低适合短距）； • 无线介质：无线电波、微波、红外线。 高频易错陷阱：双绞线单段最大有效传输距离 专转本必背数值：标准以太网中采用双绞线（UTP）通过 RJ-45 水晶头连接交换机时，单段双绞线的最大无中继有效传输距离严格限定为 100 米！超过 100 米信号衰减与畸变急剧恶化导致丢包，必须通过中继器或交换机重新放大整形！$kbsplitse$),(105, $kbsplit$[{"t":"list","id":"a3-3-4-3-b1","imp":"core","items":["==10==.0.0.0","1、==路由器与网桥的区别及异构网络互连==：^^路由器^^：==用于异构网络==，解决数据包不兼容的中转格式问题。 网桥：连接两个同类型的网络。 网络互连的实质就是把相同或异构的局域网与局域网、局域网与广域网、广域网与广域网连接起来，实现这种连接起关键作用的设备是路由器。【2007 年真题】 异构网络的解决方案：统一采用 TCP/IP 协议，并使用互连设备路由器。 IP 数据报是中间格式，独立于其他网络，分为头部和数据区。 路由器的 IP 地址至少有 2 个；路由器的目的地是连接在路由器上的一个物理网络。","2、==IP 数据报的组成与路由器==","^^IP 数据报由头部和数据区组成^^：","==1）头部：主要是为了确定在网络中进行数据传输的路由。==","==2）数据部分的长度可以改变，最大为 64KB。==","^^路由器^^：","1）功能：连接异构网络，根据路由表转发 IP 数据报。","2）工作过程：路由选择、帧格式转换、IP 数据报的转发等。","3）每个路由器应分配 2 个或多个 IP 地址，路由器每个端口的 IP 地址必须与相连子网的 IP 地址具有相同的类型号和网络号。","4）路由器功能比普通分组交换机功能更强。","3、==常见网络设备及其特点==：^^中继器^^：==放大并转发信号==，主要用于光纤中继。 集线器（HUB）：放大并转发信号，同时可以扩展网络，但不扩展网络带宽。 网桥：桥接两个同类但不同网段的网络，具备帧过滤功能。 交换机（Switch）：通过转发表实现数据帧传输，并且可以纠错，将有错误的数据帧重新发送。 路由器（Router）：连接异构网络，具备帧格式转换功能，可以将数据帧转为数据报，同时提供数据报转发服务和路由选择服务；路由器至少要配置两个或两个以上的 IP 地址。 考点：不同的网络其数据帧格式不相同。","4、==交换机与路由器的区别==：交换机（又名交换式集线器）是一种用于==电（光）信号转发的网络设备==，它可以为接入交换机的任意两个网络节点提供独享的电信号通路，其作用可以理解为将一些机器连接起来组成一个局域网。 路由器与交换机有明显区别，它的作用在于连接不同的网段并且找到网络中数据传输最合适的路径。路由器产生于交换机之后，用以连接网络中各种不同设备，它会根据信道的情况自动选择和设定路由，以最佳路径按前后顺序发送信号。路由器主要克服了交换机不能路由转发数据包的不足。 路由器（Router）是连接因特网中各局域网、广域网的设备，它会根据信道的情况自动选择和设定路由，以最佳路径按前后顺序发送信号。","5、==路由器不负责可靠性==：==路由器不负责可靠性==。 路由器工作在网络层（网络互联层），而不是物理层。","6、==连通帧格式不同的局域网应选用的设备==：==为了连通两个帧格式不相同的局域网==，应选用的互连设备是：路由器（工作在网络层）或网关（工作在应用层）。"],"title":"","ordered":false},{"t":"callout","id":"a3-3-4-3-b2","imp":"core","kind":"tip","text":"IPv6 彻底解决 IPv4 地址耗尽问题；==IPv6 地址长度为 128 位（16 字节，是 IPv4 的 4 倍）==；采用冒号十六进制表示法，分为 8 组，每组 4 位十六进制数，如 `2001:0db8:85a3:0000:0000:8a2e:0370:7334`；支持双冒号 `::` 零压缩规则（一个地址中仅允许出现一次双冒号）。","title":"考向复习提示：IPv6 地址空间与冒号十六进制表示"},{"t":"callout","id":"a3-3-4-3-b3","imp":"core","kind":"trap","text":"专转本单选常考语法陷阱：在 IPv6 地址压缩中，==双冒号 `::` 只能连续压缩一次连续的 0 组==；若一个地址出现两次双冒号（如 `2001::85a3::7334`），系统在还原时将无法判断两处各压缩了多少组零，导致歧义从而判定该地址非法！","title":"高频易错陷阱：双冒号零压缩在 IPv6 地址中只能使用一次"}]$kbsplit$::jsonb, $kbsplitse$A3-3.4.3 交换机与路由器。 10.0.0.0 1、路由器与网桥的区别及异构网络互连：路由器：用于异构网络，解决数据包不兼容的中转格式问题。 网桥：连接两个同类型的网络。 网络互连的实质就是把相同或异构的局域网与局域网、局域网与广域网、广域网与广域网连接起来，实现这种连接起关键作用的设备是路由器。【2007 年真题】 异构网络的解决方案：统一采用 TCP/IP 协议，并使用互连设备路由器。 IP 数据报是中间格式，独立于其他网络，分为头部和数据区。 路由器的 IP 地址至少有 2 个；路由器的目的地是连接在路由器上的一个物理网络。 2、IP 数据报的组成与路由器 IP 数据报由头部和数据区组成： 1）头部：主要是为了确定在网络中进行数据传输的路由。 2）数据部分的长度可以改变，最大为 64KB。 路由器： 1）功能：连接异构网络，根据路由表转发 IP 数据报。 2）工作过程：路由选择、帧格式转换、IP 数据报的转发等。 3）每个路由器应分配 2 个或多个 IP 地址，路由器每个端口的 IP 地址必须与相连子网的 IP 地址具有相同的类型号和网络号。 4）路由器功能比普通分组交换机功能更强。 3、常见网络设备及其特点：中继器：放大并转发信号，主要用于光纤中继。 集线器（HUB）：放大并转发信号，同时可以扩展网络，但不扩展网络带宽。 网桥：桥接两个同类但不同网段的网络，具备帧过滤功能。 交换机（Switch）：通过转发表实现数据帧传输，并且可以纠错，将有错误的数据帧重新发送。 路由器（Router）：连接异构网络，具备帧格式转换功能，可以将数据帧转为数据报，同时提供数据报转发服务和路由选择服务；路由器至少要配置两个或两个以上的 IP 地址。 考点：不同的网络其数据帧格式不相同。 4、交换机与路由器的区别：交换机（又名交换式集线器）是一种用于电（光）信号转发的网络设备，它可以为接入交换机的任意两个网络节点提供独享的电信号通路，其作用可以理解为将一些机器连接起来组成一个局域网。 路由器与交换机有明显区别，它的作用在于连接不同的网段并且找到网络中数据传输最合适的路径。路由器产生于交换机之后，用以连接网络中各种不同设备，它会根据信道的情况自动选择和设定路由，以最佳路径按前后顺序发送信号。路由器主要克服了交换机不能路由转发数据包的不足。 路由器（Router）是连接因特网中各局域网、广域网的设备，它会根据信道的情况自动选择和设定路由，以最佳路径按前后顺序发送信号。 5、路由器不负责可靠性：路由器不负责可靠性。 路由器工作在网络层（网络互联层），而不是物理层。 6、连通帧格式不同的局域网应选用的设备：为了连通两个帧格式不相同的局域网，应选用的互连设备是：路由器（工作在网络层）或网关（工作在应用层）。 考向复习提示：IPv6 地址空间与冒号十六进制表示 IPv6 彻底解决 IPv4 地址耗尽问题；IPv6 地址长度为 128 位（16 字节，是 IPv4 的 4 倍）；采用冒号十六进制表示法，分为 8 组，每组 4 位十六进制数，如 2001:0db8:85a3:0000:0000:8a2e:0370:7334；支持双冒号 :: 零压缩规则（一个地址中仅允许出现一次双冒号）。 高频易错陷阱：双冒号零压缩在 IPv6 地址中只能使用一次 专转本单选常考语法陷阱：在 IPv6 地址压缩中，双冒号 :: 只能连续压缩一次连续的 0 组；若一个地址出现两次双冒号（如 2001::85a3::7334），系统在还原时将无法判断两处各压缩了多少组零，导致歧义从而判定该地址非法！$kbsplitse$),(108, $kbsplit$[{"t":"list","id":"a3-3-5-1-b1","imp":"core","items":["1、==ASP 访问数据库的过程与网络安全==：^^ASP 技术访问数据库的过程^^：==在 ODBC 或者 JDBC 支持下==，","①==连接到所需要的数据库==；","②指定存储区，用于==暂存结果==；","③==发送 SQL==，数据库服务器执行 SQL，并在","②==中指定的存储区存放结果==；","④==对存储区中的结果按网页要求进行检查==，或作为共享数据提供出去。","==十一、网络安全 没有绝对安全的网络==，只能在安全性与实用性（成本）之间折中。网络信息安全措施必须能覆盖信息的存储、传输、处理等多个方面。","①^^网络安全四个方面^^：传输中断（影响信息安全的可用性）、窃听（影响机密性）、篡改（影响完整性）、伪造（影响真实性）。","2、==安全措施==：","1）真实性鉴别","2）访问控制","3）数据加密：使网络通信在被窃听的情况下仍然保证数据的安全","4）数据完整性：保护数据不被非法修改，使数据在传送前后保持完全相同","5）数据可用性","6）防止否认","7）审计管理","3、==确保信息安全的技术措施==：","（1）^^真实性鉴别^^：==对通信双方的身份和所传送信息的真伪能准确地进行鉴别==。","（2）^^访问控制^^：==控制用户对信息等资源的访问权限==，防止未经授权使用资源。","（3）^^数据加密^^：==保护数据秘密==，未经授权其内容不会显露。","（4）^^保证数据完整性^^：==保护数据不被非法修改==，使数据在传送前后保持完全相同。","（5）^^保证数据可用性^^：==保护数据在任何情况（包括系统故障）下不会丢失==。","（6）^^防止否认^^：==防止接收方或发送方抵赖==。","（7）^^审计管理^^：==监督用户活动、记录用户操作等==。","4、==网络安全的主要技术与措施==：==身份验证是网络安全的基础==；访问控制是建立在身份验证基础上的权限分配。","- ^^数据加密^^：==对称密钥加密速度快、算法简单==，但密钥管理麻烦，适用于大量数据加密；公共密钥由加密方使用接收方的公共密钥加密、接收方使用自己的私钥解密，算法复杂、加密速度慢，适用于核心数据。","- ^^数字签名^^：==适用于电子商务==，加密方使用自己的私钥加密，接收方使用发送方的公钥解密。","- ^^防火墙^^：==实现包过滤==，可以防止来自外部网络的攻击，有硬件和软件之分。","- ^^病毒^^：==是计算机程序==，具有破坏性、隐藏性、潜伏性和传播性；杀毒软件一般滞后于病毒，应以防为主、以杀为辅。","5、^^身份鉴别^^：真实性鉴别是指证实某人或某物（消息、文件、主机等）的真实身份与其所声称的身份是否相符的过程，也称为身份鉴别或身份认证，目的是防止欺诈和假冒攻击。身份鉴别一般在用户登录某个计算机系统或访问某个资源时进行，传送一些数据时也需要进行身份鉴别。 身份鉴别必须做到准确快速地将对方的真伪分辨出来。","6、^^计算机网络的脆弱性^^：==脆弱性==：^^容易遭受黑客、病毒、信息盗用等损害^^。"],"title":"","ordered":false},{"t":"callout","id":"a3-3-5-1-b2","imp":"core","kind":"tip","text":"DNS（域名系统）是分布式层次化数据库系统，域名结构自右向左级别递增：主机名.三级域名.二级域名.顶级域名（如 `www.tsinghua.edu.cn`）；顶级域名分为通用（`.com/.edu/.gov/.org`）与国家代码（`.cn/.us/.jp`）；解析方式包含==递归查询（一路问到底）与迭代查询（踢皮球式指路）==。","title":"考向复习提示：DNS 域名解析体系与递归/迭代查询"},{"t":"callout","id":"a3-3-5-1-b3","imp":"core","kind":"trap","text":"专转本高频考查单选：计算机在向外部 DNS 服务器发起域名解析请求之前，==操作系统会首先检索本地的 `hosts` 静态文本文件==（Windows 位于 `C:\\Windows\\System32\\drivers\\etc\\hosts`）；若 hosts 文件中已静态配置了该域名与 IP 的对应关系，系统将直接采用该 IP，根本不会向互联网 DNS 发送任何网络请求！","title":"高频易错陷阱：hosts 文件优先级高于外部 DNS 服务器！"}]$kbsplit$::jsonb, $kbsplitse$A3-3.5.1 信息安全基本概念。 1、ASP 访问数据库的过程与网络安全：ASP 技术访问数据库的过程：在 ODBC 或者 JDBC 支持下， ①连接到所需要的数据库； ②指定存储区，用于暂存结果； ③发送 SQL，数据库服务器执行 SQL，并在 ②中指定的存储区存放结果； ④对存储区中的结果按网页要求进行检查，或作为共享数据提供出去。 十一、网络安全 没有绝对安全的网络，只能在安全性与实用性（成本）之间折中。网络信息安全措施必须能覆盖信息的存储、传输、处理等多个方面。 ①网络安全四个方面：传输中断（影响信息安全的可用性）、窃听（影响机密性）、篡改（影响完整性）、伪造（影响真实性）。 2、安全措施： 1）真实性鉴别 2）访问控制 3）数据加密：使网络通信在被窃听的情况下仍然保证数据的安全 4）数据完整性：保护数据不被非法修改，使数据在传送前后保持完全相同 5）数据可用性 6）防止否认 7）审计管理 3、确保信息安全的技术措施： （1）真实性鉴别：对通信双方的身份和所传送信息的真伪能准确地进行鉴别。 （2）访问控制：控制用户对信息等资源的访问权限，防止未经授权使用资源。 （3）数据加密：保护数据秘密，未经授权其内容不会显露。 （4）保证数据完整性：保护数据不被非法修改，使数据在传送前后保持完全相同。 （5）保证数据可用性：保护数据在任何情况（包括系统故障）下不会丢失。 （6）防止否认：防止接收方或发送方抵赖。 （7）审计管理：监督用户活动、记录用户操作等。 4、网络安全的主要技术与措施：身份验证是网络安全的基础；访问控制是建立在身份验证基础上的权限分配。 - 数据加密：对称密钥加密速度快、算法简单，但密钥管理麻烦，适用于大量数据加密；公共密钥由加密方使用接收方的公共密钥加密、接收方使用自己的私钥解密，算法复杂、加密速度慢，适用于核心数据。 - 数字签名：适用于电子商务，加密方使用自己的私钥加密，接收方使用发送方的公钥解密。 - 防火墙：实现包过滤，可以防止来自外部网络的攻击，有硬件和软件之分。 - 病毒：是计算机程序，具有破坏性、隐藏性、潜伏性和传播性；杀毒软件一般滞后于病毒，应以防为主、以杀为辅。 5、身份鉴别：真实性鉴别是指证实某人或某物（消息、文件、主机等）的真实身份与其所声称的身份是否相符的过程，也称为身份鉴别或身份认证，目的是防止欺诈和假冒攻击。身份鉴别一般在用户登录某个计算机系统或访问某个资源时进行，传送一些数据时也需要进行身份鉴别。 身份鉴别必须做到准确快速地将对方的真伪分辨出来。 6、计算机网络的脆弱性：脆弱性：容易遭受黑客、病毒、信息盗用等损害。 考向复习提示：DNS 域名解析体系与递归/迭代查询 DNS（域名系统）是分布式层次化数据库系统，域名结构自右向左级别递增：主机名.三级域名.二级域名.顶级域名（如 www.tsinghua.edu.cn）；顶级域名分为通用（.com/.edu/.gov/.org）与国家代码（.cn/.us/.jp）；解析方式包含递归查询（一路问到底）与迭代查询（踢皮球式指路）。 高频易错陷阱：hosts 文件优先级高于外部 DNS 服务器！ 专转本高频考查单选：计算机在向外部 DNS 服务器发起域名解析请求之前，操作系统会首先检索本地的 hosts 静态文本文件（Windows 位于 C:\Windows\System32\drivers\etc\hosts）；若 hosts 文件中已静态配置了该域名与 IP 的对应关系，系统将直接采用该 IP，根本不会向互联网 DNS 发送任何网络请求！$kbsplitse$),(111, $kbsplit$[{"t":"list","id":"a3-3-5-4-b1","imp":"core","items":["7.==计算机病毒==","1、==计算机病毒的特点、危害与防范==：","- ^^特点^^：==破坏性、隐蔽性、传染性和传播性、潜伏性==。","- ^^主要危害与表现^^：","- ==可能破坏文件内容==，造成磁盘数据丢失。","- ==在磁盘上产生许多坏的扇区==，减少磁盘可用空间。","- ==删除系统的重要程序==，使系统无法启动。","- ==修改和破坏系统的设置==。","- ==盗用用户的账号和密码==。","- ==破坏主板BIOS芯片==。","- ==处于写保护状态下的软盘、U盘不会感染任何病毒==。","- ^^常见的病毒^^：==CIH、震荡波、冲击波、尼姆达等==。","- ^^杀毒软件防范^^：==开发与更新滞后于新病毒的出现==，无法百分之百保证安全；缺陷是占用系统资源；需要不断更新。","2、==防火墙的作用与局限==：防火墙位于内网和外网之间，用于==防止外部网络对内部网络的攻击==。所有进出内网和外网的数据都要经过防火墙。防火墙不能防范从网络内部发起的攻击。","3、==入侵检测对防火墙的补充==：==入侵检测技术是防火墙技术的有效补充==，它能及时发现来自外部和内部的各种攻击企图、攻击行为和任何未经授权的访问活动，保证系统资源的机密性、完整性和可用性。","4、==入侵检测、防火墙与计算机病毒==：","1）入侵检测（Intrusion Detection）是对入侵行为的检测。它通过收集和分析网络行为、安全日志、审计数据、其他网络上可以获得的信息以及计算机系统中若干关键点的信息，检查网络或系统中是否存在违反安全策略的行为和被攻击的迹象。入侵检测作为一种积极主动的安全防护技术，提供了对内部攻击、外部攻击和误操作的实时保护，在网络系统受到危害之前拦截和响应入侵。","2）防火墙（Firewall）又称防护墙、火墙，由吉尔·舍伍德于1993年发明并引入国际互联网，是一种网络安全系统。","5、==计算机病毒防范措施==：^^计算机病毒防范^^：","1）安装杀毒软件（检测与消除计算机病毒最常用的方法）。","2）闪存盘写保护。","6、==互联网防火墙==：互联网防火墙是用于==将互联网的子网（最小子网是1台计算机）与互联网的其余部分相隔离==，以维护网络信息安全的一种软件或硬件设备。 防火墙的原理：对流经它的信息进行扫描，确保进入子网和流出子网的信息的合法性；过滤掉黑客的攻击，关闭不使用的端口，禁止特定端口流出信息等。防火墙通常部署在互联网与内部网之间，内部网一侧可再设置包过滤器。"],"title":"","ordered":false},{"t":"callout","id":"a3-3-5-4-b2","imp":"core","kind":"tip","text":"• ==防火墙（Firewall）==：位于内部安全网络与外部不可信网络之间的隔离屏障，分为==包过滤防火墙（网络层/传输层过滤 IP 与端口）==、电路级网关与==应用级网关代理防火墙（深度检查应用层报文，安全性最高）==； • ==入侵检测系统（IDS）==：旁路监听网络流量，实时检测并告警可疑入侵行为（类似于网络监控摄像头）。","title":"考向复习提示：防火墙分类与入侵检测系统 IDS"},{"t":"callout","id":"a3-3-5-4-b3","imp":"core","kind":"trap","text":"专转本真题高频陷阱题：==防火墙通常只能防范来自外部网络的非法未经授权访问，绝对无法防范来自受信任内部局域网内部合法用户的恶意攻击或窃密操作，也无法防范绕过防火墙的外部调制解调器拨号连接==！常考判断题考查防火墙防护边界的局限性。","title":"高频易错陷阱：防火墙无法防范内部网络用户的恶意行为！"}]$kbsplit$::jsonb, $kbsplitse$A3-3.5.4 入侵检测、防火墙、计算机病毒。 7.计算机病毒 1、计算机病毒的特点、危害与防范： - 特点：破坏性、隐蔽性、传染性和传播性、潜伏性。 - 主要危害与表现： - 可能破坏文件内容，造成磁盘数据丢失。 - 在磁盘上产生许多坏的扇区，减少磁盘可用空间。 - 删除系统的重要程序，使系统无法启动。 - 修改和破坏系统的设置。 - 盗用用户的账号和密码。 - 破坏主板BIOS芯片。 - 处于写保护状态下的软盘、U盘不会感染任何病毒。 - 常见的病毒：CIH、震荡波、冲击波、尼姆达等。 - 杀毒软件防范：开发与更新滞后于新病毒的出现，无法百分之百保证安全；缺陷是占用系统资源；需要不断更新。 2、防火墙的作用与局限：防火墙位于内网和外网之间，用于防止外部网络对内部网络的攻击。所有进出内网和外网的数据都要经过防火墙。防火墙不能防范从网络内部发起的攻击。 3、入侵检测对防火墙的补充：入侵检测技术是防火墙技术的有效补充，它能及时发现来自外部和内部的各种攻击企图、攻击行为和任何未经授权的访问活动，保证系统资源的机密性、完整性和可用性。 4、入侵检测、防火墙与计算机病毒： 1）入侵检测（Intrusion Detection）是对入侵行为的检测。它通过收集和分析网络行为、安全日志、审计数据、其他网络上可以获得的信息以及计算机系统中若干关键点的信息，检查网络或系统中是否存在违反安全策略的行为和被攻击的迹象。入侵检测作为一种积极主动的安全防护技术，提供了对内部攻击、外部攻击和误操作的实时保护，在网络系统受到危害之前拦截和响应入侵。 2）防火墙（Firewall）又称防护墙、火墙，由吉尔·舍伍德于1993年发明并引入国际互联网，是一种网络安全系统。 5、计算机病毒防范措施：计算机病毒防范： 1）安装杀毒软件（检测与消除计算机病毒最常用的方法）。 2）闪存盘写保护。 6、互联网防火墙：互联网防火墙是用于将互联网的子网（最小子网是1台计算机）与互联网的其余部分相隔离，以维护网络信息安全的一种软件或硬件设备。 防火墙的原理：对流经它的信息进行扫描，确保进入子网和流出子网的信息的合法性；过滤掉黑客的攻击，关闭不使用的端口，禁止特定端口流出信息等。防火墙通常部署在互联网与内部网之间，内部网一侧可再设置包过滤器。 考向复习提示：防火墙分类与入侵检测系统 IDS • 防火墙（Firewall）：位于内部安全网络与外部不可信网络之间的隔离屏障，分为包过滤防火墙（网络层/传输层过滤 IP 与端口）、电路级网关与应用级网关代理防火墙（深度检查应用层报文，安全性最高）； • 入侵检测系统（IDS）：旁路监听网络流量，实时检测并告警可疑入侵行为（类似于网络监控摄像头）。 高频易错陷阱：防火墙无法防范内部网络用户的恶意行为！ 专转本真题高频陷阱题：防火墙通常只能防范来自外部网络的非法未经授权访问，绝对无法防范来自受信任内部局域网内部合法用户的恶意攻击或窃密操作，也无法防范绕过防火墙的外部调制解调器拨号连接！常考判断题考查防火墙防护边界的局限性。$kbsplitse$),(137, $kbsplit$[{"t":"list","id":"a4-4-4-6-b1","imp":"core","items":["①、互联网上视频点播一般都采用流媒体技术，支持视频直播或视频点播。","②、流媒体的特点∶可以边下载边播放。","（5）==视频监控==","①、视频监控是为银行、商场、交通管理等建立安全防范系统的重要组成部分。","②、视频监控系统主要是由摄像、传输、控制、显示、录像等部分组成。","③、人工智能特别是计算机视觉（computer vision）技术对于提高监控系统的效用有重大的作用。","1、使用数字视频的意义","①、数字视频易于使用计算机编辑、修改和处理","②、数字视频有利于存储和复制，复制不会产生失真","③、数字视频有利于传输(节省频率资源，抗干扰能力强)","④、数字视频可以通过计算机网传输","⑤、用户接收的数字图像质量更好(可达演播室水平)","⑥、数字视频容易与其它媒体（声音、文字等）组合使用","⑦、数字视频便于进行管理和检索","2、==点播电视（VOD）==：==VOD是视频点播（也称为点播电视）技术的简称==，用户可以根据自己的需要选择电视节目。VOD技术从根本上改变了用户只能被动收看电视的状况。 目前在因特网上支持视频直播或视频点播，一般采用流媒体技术。","3、==RFID、ZigBee与IP地址等知识==：RFID（射频识别）通过无线电信号对标签或射频卡进行读写，从而达到识别目标和数据交换的目的，被认为是21世纪最具发展潜力的信息技术之一。 ZigBee（紫蜂）是一种近距离、低复杂度、低功耗、低速率、低成本的双向无线通信技术，广泛应用于==船舶客舱、楼宇自动化、工业自动化等==，使用工业科学医疗（ISM）免执照频段：915MHz（美国）、868MHz（欧洲）、2.4GHz（全球）。在ZigBee协议架构中，由IEEE 802.15.4（低功耗、低成本、低速率的局域网）标准定义的是物理层和MAC层。 关系R、S有相同属性B，属于自然连接。","4、==流媒体技术的定义、应用与代表==：","^^1）定义^^：允许在窄带网上让用户一边下载一边收看（听）音视频连续媒体的技术。","^^2）应用^^：在线音频广播、实时音乐或视频点播、视频会议。","^^3）代表^^：微软公司的 WMV、ASF。 数字视频编辑器（核心软件）：Adobe Premiere、VideoStudio（会声会影）、Windows Movie Maker。 动画制作软件：MAYA、3ds max、Animator Pro、Flash。","5、^^常见声音流媒体软件^^：目前流行的声音流媒体（边下载边播放）软件有：Real 公司的 RA、微软的 WMA、苹果公司的 QuickTime。"],"title":"","ordered":false},{"t":"callout","id":"a4-4-4-6-b2","imp":"core","kind":"tip","text":"流媒体（Streaming Media）是指在网络上采用流式传输技术连续播放视音频的媒体格式；其突破性核心在于：==允许用户在音视频数据完全下载到本地之前，只需缓冲几秒即可“边下载、边解压、边播放”==，无需等待数十吉字节的完整文件下载完毕；常用协议包括 RTSP、RTMP、HLS。","title":"考向复习提示：流媒体技术概念与边下边播原理"},{"t":"callout","id":"a4-4-4-6-b3","imp":"core","kind":"trap","text":"专转本单选常考：传统 HTTP 早期下载模式必须等整个大视频文件全部保存到本地硬盘后，才能调用播放器打开；而==流媒体技术利用客户端本地环形内存缓冲区，将网络数据流转化为连续的播放数据，大大节约等待时间和本地硬盘空间==；流媒体服务器可根据客户端网络带宽动态自适应调整码率！","title":"高频易错陷阱：流媒体边下边播与传统 HTTP 下载播放的区别"}]$kbsplit$::jsonb, $kbsplitse$A4-4.4.6 流媒体。 ①、互联网上视频点播一般都采用流媒体技术，支持视频直播或视频点播。 ②、流媒体的特点∶可以边下载边播放。 （5）视频监控 ①、视频监控是为银行、商场、交通管理等建立安全防范系统的重要组成部分。 ②、视频监控系统主要是由摄像、传输、控制、显示、录像等部分组成。 ③、人工智能特别是计算机视觉（computer vision）技术对于提高监控系统的效用有重大的作用。 1、使用数字视频的意义 ①、数字视频易于使用计算机编辑、修改和处理 ②、数字视频有利于存储和复制，复制不会产生失真 ③、数字视频有利于传输(节省频率资源，抗干扰能力强) ④、数字视频可以通过计算机网传输 ⑤、用户接收的数字图像质量更好(可达演播室水平) ⑥、数字视频容易与其它媒体（声音、文字等）组合使用 ⑦、数字视频便于进行管理和检索 2、点播电视（VOD）：VOD是视频点播（也称为点播电视）技术的简称，用户可以根据自己的需要选择电视节目。VOD技术从根本上改变了用户只能被动收看电视的状况。 目前在因特网上支持视频直播或视频点播，一般采用流媒体技术。 3、RFID、ZigBee与IP地址等知识：RFID（射频识别）通过无线电信号对标签或射频卡进行读写，从而达到识别目标和数据交换的目的，被认为是21世纪最具发展潜力的信息技术之一。 ZigBee（紫蜂）是一种近距离、低复杂度、低功耗、低速率、低成本的双向无线通信技术，广泛应用于船舶客舱、楼宇自动化、工业自动化等，使用工业科学医疗（ISM）免执照频段：915MHz（美国）、868MHz（欧洲）、2.4GHz（全球）。在ZigBee协议架构中，由IEEE 802.15.4（低功耗、低成本、低速率的局域网）标准定义的是物理层和MAC层。 关系R、S有相同属性B，属于自然连接。 4、流媒体技术的定义、应用与代表： 1）定义：允许在窄带网上让用户一边下载一边收看（听）音视频连续媒体的技术。 2）应用：在线音频广播、实时音乐或视频点播、视频会议。 3）代表：微软公司的 WMV、ASF。 数字视频编辑器（核心软件）：Adobe Premiere、VideoStudio（会声会影）、Windows Movie Maker。 动画制作软件：MAYA、3ds max、Animator Pro、Flash。 5、常见声音流媒体软件：目前流行的声音流媒体（边下载边播放）软件有：Real 公司的 RA、微软的 WMA、苹果公司的 QuickTime。 考向复习提示：流媒体技术概念与边下边播原理 流媒体（Streaming Media）是指在网络上采用流式传输技术连续播放视音频的媒体格式；其突破性核心在于：允许用户在音视频数据完全下载到本地之前，只需缓冲几秒即可“边下载、边解压、边播放”，无需等待数十吉字节的完整文件下载完毕；常用协议包括 RTSP、RTMP、HLS。 高频易错陷阱：流媒体边下边播与传统 HTTP 下载播放的区别 专转本单选常考：传统 HTTP 早期下载模式必须等整个大视频文件全部保存到本地硬盘后，才能调用播放器打开；而流媒体技术利用客户端本地环形内存缓冲区，将网络数据流转化为连续的播放数据，大大节约等待时间和本地硬盘空间；流媒体服务器可根据客户端网络带宽动态自适应调整码率！$kbsplitse$),(142, $kbsplit$[{"t":"list","id":"b1-1-2-1-b1","imp":"core","items":["1、==通信：==","==（1）信息的（远距离）传递与交流。==","==（2）现代通信：使用电波或光波传递信息的技术，也称为电信（telecommunication），如电报、电话、传真、电子邮件、BBS、QQ、微信等==","2、通信系统模型","（1）==通信的三要素：==","==①信源->==","==②信道->==","==③信宿==","==①、信源：发送信息的设备==","==②、信道：供信号传播的通道。信道包括模拟信道和数字信道。（也有有线、无线之分）==","==③、信宿：接受信息的设备==","（2）举例："],"title":"","ordered":false},{"h":322,"t":"img","w":930,"id":"b1-1-2-1-b2","imp":"normal","src":"/kb-assets/theory/p88_r0_8803783ce71f5246.png","title":""},{"t":"list","id":"b1-1-2-1-b3","imp":"core","items":["3、电信号（或光信号）","==（1）通信系统中被传输的信息必须转换成某种==@@电信号(或光信号)@@ ==才能进行传输==","==（2）电信号（或光信号）两种形式：==@@模拟信号@@==与==@@数字信号@@","==①、模拟信号形式: 通过连续变化的物理量（如信号的幅度）来表示信息，例如人们打电话或者播音员播音时声音经话筒(麦克风)转换得到的电信号；==","==②、数字信号形式: 使用有限个状态(一般是2 个状态)来表示（编码）信息，例如电报机、传真机和计算机发出的信号都是数字信号==","4、信息传输模式","（1）信道的交互是指一条物理信道上允许的信号流动方向。","（2）传输模式分类","^^①、^^==单工方式==^^：信号只能进行一个方向的流动，即只能固定地由一端发，另一端收，如无线电播、电视等。^^","^^②、^^==半双工方式==^^：也称双向交替方式，即双方都可收发信息，但不可同时进行；同一时刻只限一个方向的信号传输，只能由一端发，另一端收。例如对讲机，说话和听话不能同时进行。^^","^^③、^^==全双工方式==^^：能同进进行两个方向的信号传输，即双方可同进发送和接收信号。全双工通信线路相当于2 个单工线路的组合。例如，电话就是全双工通信方式。^^","^^④、全/全双工方式：在全/半双工模式中，可以同时在不同的两处站之间进行两个方向上的传输（即一个站向第二个站传输，现时从第二个站接收）。全/全双工只能用在多点线路上。美国由政系统是全/全双工的示例，因为一个人可以将信件发往一个地址，同时接收来自另一个地址的信件。^^","5、信道带宽==信道带宽是指信道能够容纳的信号频率范围，其值为频率最大值减去频率最小值，单位为Hz.==","6、传输速率","==（1）数据传输速率（Data Transfer Rate）,是描述数据传输系统的重要技术指标之一，指单位时间内信道上所能传输的数据量。==","==（2）数据传输速率在数值上等于每秒钟传输构成数据代码的比特数。单位为比特/秒。即bps。==","==（3）信道传输速率就是数据在传输介质(信道)上的传输速率。==","7、==通信技术基础：模拟通信与数字通信==：^^模拟通信与数字通信^^：==模拟信号以连续的波形传输==，用经过调制的正弦波，调制频率远高于信号的原始频率，频率单位是 Hz（次/秒）。数字信号以数字信息直接传输，包括基带传输和频带传输（调制）。 调制解调技术：调制是数字信号转为模拟信号，解调是模拟信号转为数字信号。 信道：信号传输的通道。多路复用技术包括频分多路（模拟信号）、时分多路（数字信号）、波分多路（光纤光波）。信道可分为单工、半双工、全双工。 交换技术：电路交换、报文交换、分组交换（存储转发）。 传输介质：金属介质、光纤、无线，每种介质都可传输数字和模拟信号。","8、==通信系统的三个组成部分==：^^通信系统概念上由 3 个部分组成^^：==信源与信宿、携带了信息的信号、以及传输信号的信道==，三者缺一不可。","9、==数字传输技术：基带传输与频带传输==：数字传输技术包括基带传输（直接用数字信号传输信息）和频带传输（用数字信号对载波进行调制后传输信息）。","1）载波信号是频率比被传输信号高得多的正弦波。载波通信可传输电报、电话、传真和数据（如图像）。","2）频带传输技术：数字信号的远距离传输需要使用频带传输技术。如家庭拨号上网的 MODEM，就是把计算机输出的数字信号（只有“1”和“0”）调制成频带信号，然后送到电话线上传输。","3）数字信号的调制方法：幅移键控法（调幅）、频移键控法（调频）、相移键控法（调相）。","10、==通信三要素与通信终端==：^^通信的三要素^^：信源（信息发送者）→信道（信息传输的通道）→信宿（信息接收者）。 如有线电话通信：发话人及其话机是信源，受话人及其话机是信宿，电话线及中继器、交换机等设备是信道。 通信终端：信源中的发信设备或信宿中的收信设备，如电话机。","11、==模拟信号与数字信号的特点及通信网分类==：模拟信号是连续变化的物理量；数字信号是离散的，只有有限个状态（一般是 2 个状态）。 噪声是指==信息传输时不同信道之间信号的串扰对信道上传输信号所产生的影响==，或环境信号对信道上传输信号所产生的串扰或干扰。 模拟信号传输时易受噪声干扰，传输质量不稳定。 数字信号抗干扰能力强，差错可控制，可靠性好；可以更方便地加密，安全性更容易得到保障；可以直接由计算机进行存储、处理和管理。 通信网络分为模拟通信网、数字通信网和混合网。","12、==数字通信的优点==：==数字通信是当代通信的主流==，其优点有抗干扰能力强、易于控制差错、易于加密处理、保密强度高等。"],"title":"","ordered":false},{"t":"callout","id":"b1-1-2-1-b4","imp":"core","kind":"tip","text":"通信系统是指传递信息所需的全部软硬件总和，由五大要素构成：==信源（信息的发源地产生原始消息）→ 发送变换器（调制/编码）→ 信道（传输媒介）→ 接收变换器（解调/译码）→ 信宿（信息的终点接收者）==，并伴随不可避免的噪声源干扰。","title":"考向复习提示：现代通信系统五大逻辑组成要素"},{"t":"callout","id":"b1-1-2-1-b5","imp":"core","kind":"trap","text":"• ==模拟信号==：自变量时间和自变量因变量振幅取值都是==连续变化的（如传统麦克风输出的连续音频电压波形）==； • ==数字信号==：自变量时间和自变量因变量幅度取值都是==离散的（如二进制电压电平 0 和 1）==；切勿将“幅度离散但时间连续”的脉冲信号误认为模拟信号！","title":"高频易错陷阱：模拟信号 vs 数字信号判定标准"}]$kbsplit$::jsonb, $kbsplitse$B1-1.2.1 通信系统基本原理，信道、信源、信宿，模拟信号，数字信号。 1、通信： （1）信息的（远距离）传递与交流。 （2）现代通信：使用电波或光波传递信息的技术，也称为电信（telecommunication），如电报、电话、传真、电子邮件、BBS、QQ、微信等 2、通信系统模型 （1）通信的三要素： ①信源-> ②信道-> ③信宿 ①、信源：发送信息的设备 ②、信道：供信号传播的通道。信道包括模拟信道和数字信道。（也有有线、无线之分） ③、信宿：接受信息的设备 （2）举例： 3、电信号（或光信号） （1）通信系统中被传输的信息必须转换成某种电信号(或光信号) 才能进行传输 （2）电信号（或光信号）两种形式：模拟信号与数字信号 ①、模拟信号形式: 通过连续变化的物理量（如信号的幅度）来表示信息，例如人们打电话或者播音员播音时声音经话筒(麦克风)转换得到的电信号； ②、数字信号形式: 使用有限个状态(一般是2 个状态)来表示（编码）信息，例如电报机、传真机和计算机发出的信号都是数字信号 4、信息传输模式 （1）信道的交互是指一条物理信道上允许的信号流动方向。 （2）传输模式分类 ①、单工方式：信号只能进行一个方向的流动，即只能固定地由一端发，另一端收，如无线电播、电视等。 ②、半双工方式：也称双向交替方式，即双方都可收发信息，但不可同时进行；同一时刻只限一个方向的信号传输，只能由一端发，另一端收。例如对讲机，说话和听话不能同时进行。 ③、全双工方式：能同进进行两个方向的信号传输，即双方可同进发送和接收信号。全双工通信线路相当于2 个单工线路的组合。例如，电话就是全双工通信方式。 ④、全/全双工方式：在全/半双工模式中，可以同时在不同的两处站之间进行两个方向上的传输（即一个站向第二个站传输，现时从第二个站接收）。全/全双工只能用在多点线路上。美国由政系统是全/全双工的示例，因为一个人可以将信件发往一个地址，同时接收来自另一个地址的信件。 5、信道带宽信道带宽是指信道能够容纳的信号频率范围，其值为频率最大值减去频率最小值，单位为Hz. 6、传输速率 （1）数据传输速率（Data Transfer Rate）,是描述数据传输系统的重要技术指标之一，指单位时间内信道上所能传输的数据量。 （2）数据传输速率在数值上等于每秒钟传输构成数据代码的比特数。单位为比特/秒。即bps。 （3）信道传输速率就是数据在传输介质(信道)上的传输速率。 7、通信技术基础：模拟通信与数字通信：模拟通信与数字通信：模拟信号以连续的波形传输，用经过调制的正弦波，调制频率远高于信号的原始频率，频率单位是 Hz（次/秒）。数字信号以数字信息直接传输，包括基带传输和频带传输（调制）。 调制解调技术：调制是数字信号转为模拟信号，解调是模拟信号转为数字信号。 信道：信号传输的通道。多路复用技术包括频分多路（模拟信号）、时分多路（数字信号）、波分多路（光纤光波）。信道可分为单工、半双工、全双工。 交换技术：电路交换、报文交换、分组交换（存储转发）。 传输介质：金属介质、光纤、无线，每种介质都可传输数字和模拟信号。 8、通信系统的三个组成部分：通信系统概念上由 3 个部分组成：信源与信宿、携带了信息的信号、以及传输信号的信道，三者缺一不可。 9、数字传输技术：基带传输与频带传输：数字传输技术包括基带传输（直接用数字信号传输信息）和频带传输（用数字信号对载波进行调制后传输信息）。 1）载波信号是频率比被传输信号高得多的正弦波。载波通信可传输电报、电话、传真和数据（如图像）。 2）频带传输技术：数字信号的远距离传输需要使用频带传输技术。如家庭拨号上网的 MODEM，就是把计算机输出的数字信号（只有“1”和“0”）调制成频带信号，然后送到电话线上传输。 3）数字信号的调制方法：幅移键控法（调幅）、频移键控法（调频）、相移键控法（调相）。 10、通信三要素与通信终端：通信的三要素：信源（信息发送者）→信道（信息传输的通道）→信宿（信息接收者）。 如有线电话通信：发话人及其话机是信源，受话人及其话机是信宿，电话线及中继器、交换机等设备是信道。 通信终端：信源中的发信设备或信宿中的收信设备，如电话机。 11、模拟信号与数字信号的特点及通信网分类：模拟信号是连续变化的物理量；数字信号是离散的，只有有限个状态（一般是 2 个状态）。 噪声是指信息传输时不同信道之间信号的串扰对信道上传输信号所产生的影响，或环境信号对信道上传输信号所产生的串扰或干扰。 模拟信号传输时易受噪声干扰，传输质量不稳定。 数字信号抗干扰能力强，差错可控制，可靠性好；可以更方便地加密，安全性更容易得到保障；可以直接由计算机进行存储、处理和管理。 通信网络分为模拟通信网、数字通信网和混合网。 12、数字通信的优点：数字通信是当代通信的主流，其优点有抗干扰能力强、易于控制差错、易于加密处理、保密强度高等。 考向复习提示：现代通信系统五大逻辑组成要素 通信系统是指传递信息所需的全部软硬件总和，由五大要素构成：信源（信息的发源地产生原始消息）→ 发送变换器（调制/编码）→ 信道（传输媒介）→ 接收变换器（解调/译码）→ 信宿（信息的终点接收者），并伴随不可避免的噪声源干扰。 高频易错陷阱：模拟信号 vs 数字信号判定标准 • 模拟信号：自变量时间和自变量因变量振幅取值都是连续变化的（如传统麦克风输出的连续音频电压波形）； • 数字信号：自变量时间和自变量因变量幅度取值都是离散的（如二进制电压电平 0 和 1）；切勿将“幅度离散但时间连续”的脉冲信号误认为模拟信号！$kbsplitse$),(143, $kbsplit$[{"t":"list","id":"b1-1-2-2-b1","imp":"core","items":["1、多路复用技术","（1）==多路复用技术：多路信号使用同一条传输同时进行传输。==","（2）多路利用技术可以通信系统中降低通信成本。","（3）3 种基本方法","==①、频分多路复用（FDM）==","==②、时分多路复用（TDM）==","==③、波分多路复用（WDM）==","2、频分多路复用（FDM）","（1）^^将每个通信终端发送的信号调制在不同频率的载波上，通过频分多路复用器(MUX)将它们复合成为一个信号，然后在同一传输线路上进行传输。抵达接收端之后，借助分路器(DEMUX)把不同频率的载波分离出来，送到不同的接收设备。^^","（2）工作原理"],"title":"","ordered":false},{"h":338,"t":"img","w":821,"id":"b1-1-2-2-b2","imp":"normal","src":"/kb-assets/theory/p89_r0_e7adb73014656df0.png","title":""},{"t":"list","id":"b1-1-2-2-b3","imp":"important","items":["（3）应用场合广播电台：","^^①、中波 900 KHz(南京经济台)^^","^^②、中波1008 KHz (南京新闻台)^^","^^③、短波 15.28 MHz(英国BBC)^^","^^④、短波 15.29 MHz(VOA 美国之音)^^","^^⑤、调频104.3MHz (南京体育台)^^","^^⑥、调频105.8MHz(南京音乐台)^^","3、时分多路复用（TDM）","（1）^^各通信终端（计算机、电话）以规定的顺序和时间轮流使用同一传输线路进行数据传输^^","（2）工作原理："],"title":"","ordered":false},{"h":354,"t":"img","w":966,"id":"b1-1-2-2-b4","imp":"normal","src":"/kb-assets/theory/p89_r1_06d37919e3f64465.png","title":""},{"t":"list","id":"b1-1-2-2-b5","imp":"important","items":["（3）^^应用场合：主要使用在数字通信领域，如电话中继通信、GSM 手机、以太网等^^","4、波分多路复用（WDM）","（1）^^为提高传输效率，1 根光纤中可以同时传输几种不同波长的光波，每种光波各自传输自己所携带的信息，速率可达到 40G-100Gbit/s^^","（2）工作原理："],"title":"","ordered":false},{"h":341,"t":"img","w":1295,"id":"b1-1-2-2-b6","imp":"normal","src":"/kb-assets/theory/p89_r2_3929127100b9583d.png","title":""},{"t":"list","id":"b1-1-2-2-b7","imp":"core","items":["（3）应用：^^光纤通信、远程计算等。^^","5、交换技术","（1）从通信资源的分配角度来看，“交换”就是按照某种方式动态地分配传输线路。","（2）常见交换技术：","==①、电路交换==","==②、报文交换==","==③、分组交换==","==12、电路交换==","==（1）整个电路交换的过程包括建立线路、占用线路并进行数据传输（通信）和释放连接三个阶段。==","==（2）通话全过程中用户始络占用端到端的传输信道；不适合计算机数据通信。==","==（3）应用：电话通信（电话网）==","==13、报文交换==","==（1）先将用户的报文存储在交换机的存储器中，当所需要的输出电路空闲时，再将该报文发向接收交换机或用户终端。==","==（2）不独占线路（多用户共享一条线路）；无线路建立过程（提高了线路利用率）；支持多点传输；中间节点可进行数据格式的转换；差错检测（避免错误数的传输）；==","==（3）应用：公众电报等==","==14、分组交换==","==（1）在通信过程中，通信双方以分组为单位、使用存储-转发机制实现数据交互的通信方式，被称为分组交换。==","==（2）高效、灵活、迅速、可靠；需要排除，造成一定的延时；需要携带首部，也造成一定开销。==","==（3）应用：交换式以太局域网、公用数据网（传统的广域网）、互联网（Internet）、移动通信网等==","6、有线通信","（1）^^需使用物理介质进行信号传输的是有线通信，例如： 金属导体（双绞线、同轴电缆），传输电流信号 光导纤维（简称光纤），传输光信号。^^","7、==信道的传输模式==：信道的交互方式是指==在一条物理信道上所允许的信号流动方向==，可分为四种：","1）单工方式：信号只能在一个方向上流动，即固定地由一端发送、另一端接收，如无线电广播、电视等。","2）半双工方式：也称双向交替方式，双方都可收发信息，但不能同时进行，同一时刻只允许一个方向的信号传输，只能由一端发送、另一端接收，例如对讲机，说话和听话不能同时进行。","3）全双工方式：能同时进行两个方向的信号传输，即双方可同时发送和接收信号。全双工通信线路相当于两个单工线路的组合，例如电话。","8、==码分多路复用的特点==：码分多路复用技术具有频谱利用率高、抗干扰能力强、保密性强、语音质量好等优点，还可以减少投资、降低运行成本，主要用于==无线通信系统==，特别是移动通信系统。","9、^^帧中继（Frame Relay）^^：","①^^帧中继是在用户—网络接口之间提供用户信息流双向传输^^，并保持信息顺序不变的一种承载业务。","②^^帧中继是一种分组交换技术^^，使用一组规程将数据信息以帧的形式（帧中继协议）有效传送；它使用的是逻辑连接而不是物理连接，在一个物理连接上可复用多个逻辑连接，可实现带宽的动态分配。","③^^用户信息以帧为单位进行传输^^，并对用户信息流进行统计复用。","④它是由 X.25 分组交换技术发展起来的一种传输技术。","10、^^电路交换建立固定物理链路，实时性好^^：^^电路交换需要在通信双方之间建立一条固定的物理链路^^，实时性好。","11、^^码分多路复用（CDM）^^：码分多路复用是采用不同的编码来区分各路原始信号的一种复用方式。与 FDM、TDM 不同，它既共享信道的频率，又共享时间。","12、^^专线组网^^：","1）单位组建广域网时，租用电信局提供的远程数字通信线路（如光纤高速传输干线）是一种可行的方案。","^^2）优点^^：可以实现点到点、7 天×24 小时不间断通信，通信质量好。","^^3）缺点^^：费用与线路的容量和跨越的距离有关。"],"title":"","ordered":false},{"t":"callout","id":"b1-1-2-2-b8","imp":"core","kind":"tip","text":"• 通信方向模式：==单工（广播/无线电台，只能单向发送）、半双工（对讲机，能双向交替不能同时）、全双工（电话/以太网，能同时双向发送）==； • 数据交换方式：==电路交换（独占物理线路实时性高）、报文交换（存储转发无长度限制）、分组交换（将大报文拆分为定长分组存储转发，Internet 核心基础）==。","title":"考向复习提示：信道传输模式与交换技术演进"},{"t":"callout","id":"b1-1-2-2-b9","imp":"core","kind":"trap","text":"专转本经典计算陷阱： • ==波特率（Baud）是调制速率（每秒传输的码元个数）==； • ==比特率（bps）是数据传输速率（每秒传输的二进制比特数）==； • 二者换算公式：==`S = B × log2 N`==（N 为调制电平状态数）；当采用 16 进制 QAM 调制时（N=16），每个码元携带 `log2 16 = 4` 个比特，此时比特率恰好是波特率的 4 倍！","title":"高频易错陷阱：波特率（Baud）与比特率（bps）的数学换算"}]$kbsplit$::jsonb, $kbsplitse$B1-1.2.2 信道的传输模式，信道的带宽，信道的传输速率，多路复用技术，交换技术。 1、多路复用技术 （1）多路复用技术：多路信号使用同一条传输同时进行传输。 （2）多路利用技术可以通信系统中降低通信成本。 （3）3 种基本方法 ①、频分多路复用（FDM） ②、时分多路复用（TDM） ③、波分多路复用（WDM） 2、频分多路复用（FDM） （1）将每个通信终端发送的信号调制在不同频率的载波上，通过频分多路复用器(MUX)将它们复合成为一个信号，然后在同一传输线路上进行传输。抵达接收端之后，借助分路器(DEMUX)把不同频率的载波分离出来，送到不同的接收设备。 （2）工作原理 （3）应用场合广播电台： ①、中波 900 KHz(南京经济台) ②、中波1008 KHz (南京新闻台) ③、短波 15.28 MHz(英国BBC) ④、短波 15.29 MHz(VOA 美国之音) ⑤、调频104.3MHz (南京体育台) ⑥、调频105.8MHz(南京音乐台) 3、时分多路复用（TDM） （1）各通信终端（计算机、电话）以规定的顺序和时间轮流使用同一传输线路进行数据传输 （2）工作原理： （3）应用场合：主要使用在数字通信领域，如电话中继通信、GSM 手机、以太网等 4、波分多路复用（WDM） （1）为提高传输效率，1 根光纤中可以同时传输几种不同波长的光波，每种光波各自传输自己所携带的信息，速率可达到 40G-100Gbit/s （2）工作原理： （3）应用：光纤通信、远程计算等。 5、交换技术 （1）从通信资源的分配角度来看，“交换”就是按照某种方式动态地分配传输线路。 （2）常见交换技术： ①、电路交换 ②、报文交换 ③、分组交换 12、电路交换 （1）整个电路交换的过程包括建立线路、占用线路并进行数据传输（通信）和释放连接三个阶段。 （2）通话全过程中用户始络占用端到端的传输信道；不适合计算机数据通信。 （3）应用：电话通信（电话网） 13、报文交换 （1）先将用户的报文存储在交换机的存储器中，当所需要的输出电路空闲时，再将该报文发向接收交换机或用户终端。 （2）不独占线路（多用户共享一条线路）；无线路建立过程（提高了线路利用率）；支持多点传输；中间节点可进行数据格式的转换；差错检测（避免错误数的传输）； （3）应用：公众电报等 14、分组交换 （1）在通信过程中，通信双方以分组为单位、使用存储-转发机制实现数据交互的通信方式，被称为分组交换。 （2）高效、灵活、迅速、可靠；需要排除，造成一定的延时；需要携带首部，也造成一定开销。 （3）应用：交换式以太局域网、公用数据网（传统的广域网）、互联网（Internet）、移动通信网等 6、有线通信 （1）需使用物理介质进行信号传输的是有线通信，例如： 金属导体（双绞线、同轴电缆），传输电流信号 光导纤维（简称光纤），传输光信号。 7、信道的传输模式：信道的交互方式是指在一条物理信道上所允许的信号流动方向，可分为四种： 1）单工方式：信号只能在一个方向上流动，即固定地由一端发送、另一端接收，如无线电广播、电视等。 2）半双工方式：也称双向交替方式，双方都可收发信息，但不能同时进行，同一时刻只允许一个方向的信号传输，只能由一端发送、另一端接收，例如对讲机，说话和听话不能同时进行。 3）全双工方式：能同时进行两个方向的信号传输，即双方可同时发送和接收信号。全双工通信线路相当于两个单工线路的组合，例如电话。 8、码分多路复用的特点：码分多路复用技术具有频谱利用率高、抗干扰能力强、保密性强、语音质量好等优点，还可以减少投资、降低运行成本，主要用于无线通信系统，特别是移动通信系统。 9、帧中继（Frame Relay）： ①帧中继是在用户—网络接口之间提供用户信息流双向传输，并保持信息顺序不变的一种承载业务。 ②帧中继是一种分组交换技术，使用一组规程将数据信息以帧的形式（帧中继协议）有效传送；它使用的是逻辑连接而不是物理连接，在一个物理连接上可复用多个逻辑连接，可实现带宽的动态分配。 ③用户信息以帧为单位进行传输，并对用户信息流进行统计复用。 ④它是由 X.25 分组交换技术发展起来的一种传输技术。 10、电路交换建立固定物理链路，实时性好：电路交换需要在通信双方之间建立一条固定的物理链路，实时性好。 11、码分多路复用（CDM）：码分多路复用是采用不同的编码来区分各路原始信号的一种复用方式。与 FDM、TDM 不同，它既共享信道的频率，又共享时间。 12、专线组网： 1）单位组建广域网时，租用电信局提供的远程数字通信线路（如光纤高速传输干线）是一种可行的方案。 2）优点：可以实现点到点、7 天×24 小时不间断通信，通信质量好。 3）缺点：费用与线路的容量和跨越的距离有关。 考向复习提示：信道传输模式与交换技术演进 • 通信方向模式：单工（广播/无线电台，只能单向发送）、半双工（对讲机，能双向交替不能同时）、全双工（电话/以太网，能同时双向发送）； • 数据交换方式：电路交换（独占物理线路实时性高）、报文交换（存储转发无长度限制）、分组交换（将大报文拆分为定长分组存储转发，Internet 核心基础）。 高频易错陷阱：波特率（Baud）与比特率（bps）的数学换算 专转本经典计算陷阱： • 波特率（Baud）是调制速率（每秒传输的码元个数）； • 比特率（bps）是数据传输速率（每秒传输的二进制比特数）； • 二者换算公式：S = B × log2 N（N 为调制电平状态数）；当采用 16 进制 QAM 调制时（N=16），每个码元携带 log2 16 = 4 个比特，此时比特率恰好是波特率的 4 倍！$kbsplitse$),(160, $kbsplit$[{"t":"list","id":"b1-1-5-1-b1","imp":"core","items":["1、数据：数据（data）是事实或观察的结果，是对客观事物的逻辑归纳，是用于表示客观事物的未经加工的原始素材。","2、==数据由数据库管理系统统一管理和控制==：==数据库的共享会带来安全隐患==，而数据库的共享是并发共享，即多个用户可以同时存取数据库中的数据，甚至可以同时存取同一个数据，这又会带来不同用户间相互干扰的隐患。另外，数据库中数据的正确与一致也必须得到保障。为此，数据库管理系统还必须提供以下几方面的数据控制功能。","1. ^^数据的安全性保护^^：==保护数据以防止不合法使用造成的数据泄密和破坏==，每个用户只能按规定对某些数据以某些方式进行使用和处理。","2. ^^数据的完整性检查^^：==数据的完整性指数据的正确性、有效性和相容性==，完整性检查将数据控制在有效的范围内，并保证数据之间满足一定的关系。","3、==信息系统的开发与管理==：","1）系统规划。任务是对应用需求、现行系统进行调查分析，进行可行性分析，并完成系统的初步方案和项目开发计划。信息系统的规划和实现过程一般采用自顶向下规划和分析、自底向上设计和实现。","2）系统分析。即需求分析，是开发信息系统最基础和最重要的阶段。采用系统工程的思想和方法，把复杂的对象分解成简单的组成部分，提出这些部分所需数据的基本属性和彼此间的关系。需求分析的重点是“数据”和“处理”，通过调研和分析获得用户对信息、处理、安全和完整性的需求。系统分析中经常采用结构化分析方法（SA），自顶向下逐层分解分析系统，并用数据流程图和数据字典来表达数据和处理过程的关系。","4、==数据库管理系统的性质与产品==：==DBMS 是一个系统软件==，是操纵、管理大型数据库的大型软件。用户只有通过 DBMS 才能访问数据库中的数据；DBA 也只有通过 DBMS 才能对数据库进行管理与维护，不允许绕过 DBMS 直接访问数据。DBMS 不一定都是关系数据库系统；关系数据库系统（RDBMS）是采用关系模型的数据库。常见的关系型数据库系统有 ORACLE、DB2、Microsoft SQL Server、Access、VFP、Sybase、MySQL、PostgreSQL 等。","5、==数据独立性==：^^数据独立于程序。1）逻辑独立性^^：==用户的应用程序与数据库的逻辑结构相互独立==，数据逻辑结构改变时应用程序不需要改变。2）物理独立性：用户的应用程序与存储在数据库中的数据相互独立，数据的物理存储改变不影响用户的应用程序。","6、==数据库的物理结构设计==：^^物理结构设计^^：==确定数据库在外存上的存储结构和存取方法==，依赖硬件，目标是提高数据库性能并有效利用存储空间。设计阶段涉及三个模型：概念模型、逻辑模型和物理模型；E-R 图独立于后续的一切设计。","7、==数据库的体系结构：三级模式与两级映射==：","- ^^三级模式 - 外模式（用户模式）^^：==外模式/模式映像确定逻辑独立性==。","- ^^模式^^：==描述全局数据的逻辑结构和特征==。","- ^^内模式^^：==模式/内模式映像确定物理独立性==。","- ^^两级映射^^：==外模式/概念模式、概念模式/内模式==。","- SQL 数据库的三级体系结构由外模式、模式和内模式构成：","- ==外模式 子模式 用户模式 局部模式 视图==，一个数据库可以有多个外模式。","- ==模式 逻辑模式 基本表==，一个数据库只有一个模式。","- ==内模式 存储模式 文件==，一个数据库只有一个内模式。"],"title":"","ordered":false},{"t":"callout","id":"b1-1-5-1-b2","imp":"core","kind":"tip","text":"数据库系统（DBS）由==数据库（DB，物理存储的数据集合）、数据库管理系统（DBMS，如 MySQL/Oracle 等系统软件）、数据库管理员（DBA）与应用系统==构成；相比传统文件系统的绝对优势是：==数据结构化、极高的数据共享性与低冗余度、高数据独立性、由 DBMS 统一安全控制==。","title":"考向复习提示：数据库系统（DBS）三大组成与核心优势"},{"t":"callout","id":"b1-1-5-1-b3","imp":"core","kind":"trap","text":"专转本经典常考题（三级模式与两级映像）： • ==物理独立性==：由“模式/内模式映像”保证，当数据库的物理存储结构（如换硬盘、改索引文件）改变时，用户的逻辑模式与应用程序无需修改； • ==逻辑独立性==：由“外模式/模式映像”保证，当数据库的全局总体逻辑结构改变时，用户的外模式（视图）与上层应用程序保持不变！","title":"高频易错陷阱：物理独立性 vs 逻辑独立性的判定界限"}]$kbsplit$::jsonb, $kbsplitse$B1-1.5.1 数据库系统的组成和特点。 1、数据：数据（data）是事实或观察的结果，是对客观事物的逻辑归纳，是用于表示客观事物的未经加工的原始素材。 2、数据由数据库管理系统统一管理和控制：数据库的共享会带来安全隐患，而数据库的共享是并发共享，即多个用户可以同时存取数据库中的数据，甚至可以同时存取同一个数据，这又会带来不同用户间相互干扰的隐患。另外，数据库中数据的正确与一致也必须得到保障。为此，数据库管理系统还必须提供以下几方面的数据控制功能。 1. 数据的安全性保护：保护数据以防止不合法使用造成的数据泄密和破坏，每个用户只能按规定对某些数据以某些方式进行使用和处理。 2. 数据的完整性检查：数据的完整性指数据的正确性、有效性和相容性，完整性检查将数据控制在有效的范围内，并保证数据之间满足一定的关系。 3、信息系统的开发与管理： 1）系统规划。任务是对应用需求、现行系统进行调查分析，进行可行性分析，并完成系统的初步方案和项目开发计划。信息系统的规划和实现过程一般采用自顶向下规划和分析、自底向上设计和实现。 2）系统分析。即需求分析，是开发信息系统最基础和最重要的阶段。采用系统工程的思想和方法，把复杂的对象分解成简单的组成部分，提出这些部分所需数据的基本属性和彼此间的关系。需求分析的重点是“数据”和“处理”，通过调研和分析获得用户对信息、处理、安全和完整性的需求。系统分析中经常采用结构化分析方法（SA），自顶向下逐层分解分析系统，并用数据流程图和数据字典来表达数据和处理过程的关系。 4、数据库管理系统的性质与产品：DBMS 是一个系统软件，是操纵、管理大型数据库的大型软件。用户只有通过 DBMS 才能访问数据库中的数据；DBA 也只有通过 DBMS 才能对数据库进行管理与维护，不允许绕过 DBMS 直接访问数据。DBMS 不一定都是关系数据库系统；关系数据库系统（RDBMS）是采用关系模型的数据库。常见的关系型数据库系统有 ORACLE、DB2、Microsoft SQL Server、Access、VFP、Sybase、MySQL、PostgreSQL 等。 5、数据独立性：数据独立于程序。1）逻辑独立性：用户的应用程序与数据库的逻辑结构相互独立，数据逻辑结构改变时应用程序不需要改变。2）物理独立性：用户的应用程序与存储在数据库中的数据相互独立，数据的物理存储改变不影响用户的应用程序。 6、数据库的物理结构设计：物理结构设计：确定数据库在外存上的存储结构和存取方法，依赖硬件，目标是提高数据库性能并有效利用存储空间。设计阶段涉及三个模型：概念模型、逻辑模型和物理模型；E-R 图独立于后续的一切设计。 7、数据库的体系结构：三级模式与两级映射： - 三级模式 - 外模式（用户模式）：外模式/模式映像确定逻辑独立性。 - 模式：描述全局数据的逻辑结构和特征。 - 内模式：模式/内模式映像确定物理独立性。 - 两级映射：外模式/概念模式、概念模式/内模式。 - SQL 数据库的三级体系结构由外模式、模式和内模式构成： - 外模式 子模式 用户模式 局部模式 视图，一个数据库可以有多个外模式。 - 模式 逻辑模式 基本表，一个数据库只有一个模式。 - 内模式 存储模式 文件，一个数据库只有一个内模式。 考向复习提示：数据库系统（DBS）三大组成与核心优势 数据库系统（DBS）由数据库（DB，物理存储的数据集合）、数据库管理系统（DBMS，如 MySQL/Oracle 等系统软件）、数据库管理员（DBA）与应用系统构成；相比传统文件系统的绝对优势是：数据结构化、极高的数据共享性与低冗余度、高数据独立性、由 DBMS 统一安全控制。 高频易错陷阱：物理独立性 vs 逻辑独立性的判定界限 专转本经典常考题（三级模式与两级映像）： • 物理独立性：由“模式/内模式映像”保证，当数据库的物理存储结构（如换硬盘、改索引文件）改变时，用户的逻辑模式与应用程序无需修改； • 逻辑独立性：由“外模式/模式映像”保证，当数据库的全局总体逻辑结构改变时，用户的外模式（视图）与上层应用程序保持不变！$kbsplitse$),(162, $kbsplit$[{"t":"list","id":"b1-1-5-3-b1","imp":"core","items":["==言，允许用户在高层数据结构上工作，是关系数据库的标准语言。==","（2）SQL 由四部分组成：","1、==关系数据模型==：","1）用二维表结构表示实体集以及实体集之间联系的数据模型。","2）信息世界中的一个实体集反映在关系数据库中可以是一个关系（二维表）。","3）地位：使用最为广泛。","2、==主键==：==从候选关键字中选定一个作为关键字==，称之为该关系的主关键字。主键是唯一标识元组的属性或属性组。","3、==关系数据模型的完整性约束（含外键）==：==关系模式用 R(A1, A2, …, An) 表示==，仅仅说明关系的语法，但并不是每个合乎语法的元组都能成为 R 的元组，它还要受到语义的限制。数据的语义不但会限制属性的值，还会制约属性间的关系，这些约束可以用来保证数据库中数据的正确性，称为关系数据模型的完整性约束。 三类完整性规则： 实体完整性：若属性 A 为关系 R 的主键，则 A 不能为空值（即其值处于未知状态，记为 Null）或重值。 引用完整性：R1 的外键 F 要么是被引用关系 R2 中某一元组实际存在的主键值，要么为空值。简单地说，即要求在关系中不允许引用不存在的实体（即元组）。","4、==关系数据模式==：^^一个关系数据模式（注意^^：==不是关系模型）就是一个具体的关系的结构==。如上述学生这个关系的具体结构（包含哪几个列、放什么数据），就是一个关系数据模式。 记忆：理解时，一个关系模式就是一个表格的具体的表格结构。 关系模式的表示形式是 R(A1, A2, …, An)，R 是关系模式名，Ai 都是属性名。如学生关系模式表示是：学生（学号，姓名，性别）。 注意：考试时，给出的关系模式中加上下划线的属性或属性组，表示是主键。","5、==关系模型的限制条件==：^^在关系模型中，对每个关系有如下的限制^^：==属性名不能相同而其值域可能相同==；属性不可再分；不允许出现相同的元组；元组次序可以任意交换，属性的顺序也可以任意交换。","6、==关系数据模型的存储结构==：==在关系数据模型中==，实体集、实体集之间的联系都用二维表来表示。在支持关系模型的数据库（即关系数据库）的物理组织中，二维表以文件形式存储。在大多数数据库中，二维表与操作系统中的文件相对应。"],"title":"","ordered":false},{"t":"callout","id":"b1-1-5-3-b2","imp":"core","kind":"tip","text":"关系数据模型严格建立在集合代数理论之上： • ==关系（Relation）==对应一张==二维表==； • ==元组（Tuple）==对应表中的一行记录； • ==属性（Attribute）==对应表中的一列（字段）； • ==域（Domain）==对应属性的取值范围； • ==候选码与主码（Primary Key）==能唯一标识表中的一个元组。","title":"考向复习提示：关系数据模型核心术语对号入座"},{"t":"callout","id":"b1-1-5-3-b3","imp":"core","kind":"trap","text":"专转本真题必考规范化性质：一个合法的关系必须满足： 1. ==关系中的每一个属性（分量）都必须是不可再分的原子项（满足第一范式 1NF），严禁表中套表==； 2. ==同一个关系中绝对不允许出现两个完全相同的元组行（由主键唯一性约束保证）==； 3. 行的排列顺序和列的排列顺序在集合意义上均是任意且无关紧要的！","title":"高频易错陷阱：关系的数学性质严禁包含重复元组与多值属性！"}]$kbsplit$::jsonb, $kbsplitse$B1-1.5.3 关系数据模型。 言，允许用户在高层数据结构上工作，是关系数据库的标准语言。 （2）SQL 由四部分组成： 1、关系数据模型： 1）用二维表结构表示实体集以及实体集之间联系的数据模型。 2）信息世界中的一个实体集反映在关系数据库中可以是一个关系（二维表）。 3）地位：使用最为广泛。 2、主键：从候选关键字中选定一个作为关键字，称之为该关系的主关键字。主键是唯一标识元组的属性或属性组。 3、关系数据模型的完整性约束（含外键）：关系模式用 R(A1, A2, …, An) 表示，仅仅说明关系的语法，但并不是每个合乎语法的元组都能成为 R 的元组，它还要受到语义的限制。数据的语义不但会限制属性的值，还会制约属性间的关系，这些约束可以用来保证数据库中数据的正确性，称为关系数据模型的完整性约束。 三类完整性规则： 实体完整性：若属性 A 为关系 R 的主键，则 A 不能为空值（即其值处于未知状态，记为 Null）或重值。 引用完整性：R1 的外键 F 要么是被引用关系 R2 中某一元组实际存在的主键值，要么为空值。简单地说，即要求在关系中不允许引用不存在的实体（即元组）。 4、关系数据模式：一个关系数据模式（注意：不是关系模型）就是一个具体的关系的结构。如上述学生这个关系的具体结构（包含哪几个列、放什么数据），就是一个关系数据模式。 记忆：理解时，一个关系模式就是一个表格的具体的表格结构。 关系模式的表示形式是 R(A1, A2, …, An)，R 是关系模式名，Ai 都是属性名。如学生关系模式表示是：学生（学号，姓名，性别）。 注意：考试时，给出的关系模式中加上下划线的属性或属性组，表示是主键。 5、关系模型的限制条件：在关系模型中，对每个关系有如下的限制：属性名不能相同而其值域可能相同；属性不可再分；不允许出现相同的元组；元组次序可以任意交换，属性的顺序也可以任意交换。 6、关系数据模型的存储结构：在关系数据模型中，实体集、实体集之间的联系都用二维表来表示。在支持关系模型的数据库（即关系数据库）的物理组织中，二维表以文件形式存储。在大多数数据库中，二维表与操作系统中的文件相对应。 考向复习提示：关系数据模型核心术语对号入座 关系数据模型严格建立在集合代数理论之上： • 关系（Relation）对应一张二维表； • 元组（Tuple）对应表中的一行记录； • 属性（Attribute）对应表中的一列（字段）； • 域（Domain）对应属性的取值范围； • 候选码与主码（Primary Key）能唯一标识表中的一个元组。 高频易错陷阱：关系的数学性质严禁包含重复元组与多值属性！ 专转本真题必考规范化性质：一个合法的关系必须满足： 1. 关系中的每一个属性（分量）都必须是不可再分的原子项（满足第一范式 1NF），严禁表中套表； 2. 同一个关系中绝对不允许出现两个完全相同的元组行（由主键唯一性约束保证）； 3. 行的排列顺序和列的排列顺序在集合意义上均是任意且无关紧要的！$kbsplitse$),(163, $kbsplit$[{"t":"list","id":"b1-1-5-4-b1","imp":"core","items":["①、==数据定义语言==，即SQL DDL，用于定义SQL 模式、基本表、视图、索引等结构。主要命令语句：","CREATE（创建）、ALTER（修改）、DROP（删除）。","②、==数据操纵语言==，即SQL DML。主要命令语言：INSERT（插入）、UPDATE（更新）、DELETE（删除）","③、==数据查询语言==，即SQL DQL。主要命令语言：SELECT（查询），有些教材中将SELECT 归入数据操纵语言中。","④、==数据控制语言==，即SQL DCL，这一部分包括对基本表和视图的授权、完整性规则的描述、事务控制等内容。","1、数据库设计阶段：","（1）需求分析","（2）@@概念结构设计(E-R 模型)@@：主要采用E-R 模型进行设计，包括画E-R 图。","^^数据库系统的全局概念结构模式独立于具体的计算机和DBMS。^^","①、==E-R 图也称实体-联系图(Entity Relationship Diagram)，提供了表示实体类型、属性和联系的方法，用来描述, ，用来描述，与具体的数据库管理系统及软硬件环境无关.==","==②、用“==@@矩形框@@==”表示实体型，矩形框内写明==@@实体名称@@==；==","==③、用“==@@椭圆图框@@==”或圆角矩形表示==@@实体的属性@@==，并用“实心线段”将其与相应关系的“实体型”连接起来；==","==④、用”==@@菱形框@@==“表示==@@实体型之间的联系@@==成因，在菱形框内写明联系名，并用”实心线段“分别与有关实体型连接起来，同时在”实心线段“旁标上联系的类型（==@@1:1,1:n 或m:n@@==）。=="],"title":"","ordered":false},{"h":346,"t":"img","w":718,"id":"b1-1-5-4-b2","imp":"normal","src":"/kb-assets/theory/p100_r0_6e668cf2c73c70d5.png","title":""},{"t":"list","id":"b1-1-5-4-b3","imp":"core","items":["（3）==逻辑结构设计==将Ｅ－Ｒ图中实体之间联系或实体可以转换成为关系。","（4）==物理结构设计==","（5）实施","（6）运行与维护","2、==自然连接与关系数据库语言==","^^自然连接^^：","==1）二元操作==","2）特殊的等值连接；","3）要求两个关系中进行比较的属性必须是相同的属性列，并且在结果中把重名的属性列去掉。","关系代数的完备操作集：并、差、广义笛卡尔积、投影、选择。","^^关系数据库语言^^：","1）性质：关系数据库语言是一种非过程语言；","2）SQL 语句是用户与数据库的接口，既可在联机交互方式下使用，又可嵌入到宿主语言中使用；","3）代表：SQL（Structured Query Language，结构化查询语言）。","3、==关系代数完备操作集与 SQL 语言的特点==：","① ^^完备操作集^^：==并、差、广义笛卡尔积、投影、选择五种操作是基本操作==，其他所有操作均可用这五种基本操作来表达。","② SQL 的 SELECT 查询可以对查询结果（仍是一个关系）排序，既可升序、降序，也可升序与降序组合排序。","③ SQL 可以进行求平均值、求最大值、求最小值、统计个数、分类汇总等各种计算。","④ ==SQL 是基于关系代数和关系运算的语言==。","⑤ ==关系数据模型的存取路径对用户透明==。","4、==关系的运算分类==：关系的运算分为==集合运算（并、交、差）和专门的关系运算（选择、投影、连接）==。 并、交、差的前提是两个关系的关系模式相同，也就是属性的个数和属性名相同，并且对应的属性取自相同的域。并运算记作 R∪S。","5、==关系运算要点==：^^二维表的主要运算^^：","- ^^选择运算^^：==一元运算==；新关系中的元组（行）是原关系中元组的子集，结果关系的属性（列）与原关系相同。","- ^^投影运算^^：==一元运算==；新关系中的属性（列）是原关系属性的子集，元组（行）数量可能减少（重复行被合并）。","- ^^连接运算^^：==二元运算==；按两个关系的共有属性（共同属性）把它们组合起来。 传统的集合运算（二元运算）：","- ^^特点^^：参加运算的两个关系要具有相同的模式（属性个数相同、对应属性的域相同）；操作的对象与结果都是关系。","- ^^并操作^^：==结果为属于两个关系的所有元组==，重复元组只保留一个。","6、==连接操作==：连接是从关系 R 和 S 的广义笛卡尔积中选取属性值之间满足某一 θ 运算的元组，记为 R⋈_{iθj}S，其中 i 表示关系 R 的第 i 个属性，j 表示关系 S 的第 j 个属性，θ 是算术比较符。连接的形式定义如下： R⋈_{iθj}S σ_{iθ(p+j)}(R×S) 即在 R 和 S 的广义笛卡尔积中挑选第 i 个属性和第 p+j 个属性满足 θ 运算的元组，其中 p 为关系 R 的属性个数。如果 θ 是等号“”，这个连接操作称为“等值连接”。 口诀：写出属性名，十字交叉确定元组，按照连接条件筛选元组。","7、==并操作==：==并操作是二元操作==，它要求参与操作的两个关系具有相同的关系模式。其作用是将两个关系组合成一个新的关系。根据集合论的定义，并操作创建的新关系中的每一个元组或者属于第一个关系，或者属于第二个关系，或者在两个关系中皆有；重复的元组只保留一个。"],"title":"","ordered":false},{"h":824,"t":"img","w":1350,"id":"b1-1-5-4-b4","imp":"normal","src":"/kb-assets/theory/p101_r0_139f280e17082ca7.png","title":""},{"t":"callout","id":"b1-1-5-4-b5","imp":"core","kind":"tip","text":"• 传统集合运算：并（∪）、交（∩）、差（-）、笛卡尔积（×，元组数相乘，属性数相加）； • 专门关系代数运算：==选择（σ，横向选出满足条件的元组行）、投影（π，纵向选出指定的一组列属性并自动消除重复行）、连接（⋈，笛卡尔积后按条件筛选）、除运算（÷）==。","title":"考向复习提示：传统集合运算 vs 专门关系代数运算"},{"t":"callout","id":"b1-1-5-4-b6","imp":"core","kind":"trap","text":"专转本单选高频陷阱题： • ==“选择（Selection，用符号 σ 表示）”是“横向按行切”==（从表中挑选出满足 WHERE 条件的记录行）； • ==“投影（Projection，用符号 π 表示）”是“纵向按列切”==（从表中挑选出需要的字段列，并且数学定义上必须自动去除重复出现的行）；考试常偷换横切与纵切方向！","title":"高频易错陷阱：选择与投影动作记忆口诀"}]$kbsplit$::jsonb, $kbsplitse$B1-1.5.4 关系运算。 ①、数据定义语言，即SQL DDL，用于定义SQL 模式、基本表、视图、索引等结构。主要命令语句： CREATE（创建）、ALTER（修改）、DROP（删除）。 ②、数据操纵语言，即SQL DML。主要命令语言：INSERT（插入）、UPDATE（更新）、DELETE（删除） ③、数据查询语言，即SQL DQL。主要命令语言：SELECT（查询），有些教材中将SELECT 归入数据操纵语言中。 ④、数据控制语言，即SQL DCL，这一部分包括对基本表和视图的授权、完整性规则的描述、事务控制等内容。 1、数据库设计阶段： （1）需求分析 （2）概念结构设计(E-R 模型)：主要采用E-R 模型进行设计，包括画E-R 图。 数据库系统的全局概念结构模式独立于具体的计算机和DBMS。 ①、E-R 图也称实体-联系图(Entity Relationship Diagram)，提供了表示实体类型、属性和联系的方法，用来描述, ，用来描述，与具体的数据库管理系统及软硬件环境无关. ②、用“矩形框”表示实体型，矩形框内写明实体名称； ③、用“椭圆图框”或圆角矩形表示实体的属性，并用“实心线段”将其与相应关系的“实体型”连接起来； ④、用”菱形框“表示实体型之间的联系成因，在菱形框内写明联系名，并用”实心线段“分别与有关实体型连接起来，同时在”实心线段“旁标上联系的类型（1:1,1:n 或m:n）。 （3）逻辑结构设计将Ｅ－Ｒ图中实体之间联系或实体可以转换成为关系。 （4）物理结构设计 （5）实施 （6）运行与维护 2、自然连接与关系数据库语言 自然连接： 1）二元操作 2）特殊的等值连接； 3）要求两个关系中进行比较的属性必须是相同的属性列，并且在结果中把重名的属性列去掉。 关系代数的完备操作集：并、差、广义笛卡尔积、投影、选择。 关系数据库语言： 1）性质：关系数据库语言是一种非过程语言； 2）SQL 语句是用户与数据库的接口，既可在联机交互方式下使用，又可嵌入到宿主语言中使用； 3）代表：SQL（Structured Query Language，结构化查询语言）。 3、关系代数完备操作集与 SQL 语言的特点： ① 完备操作集：并、差、广义笛卡尔积、投影、选择五种操作是基本操作，其他所有操作均可用这五种基本操作来表达。 ② SQL 的 SELECT 查询可以对查询结果（仍是一个关系）排序，既可升序、降序，也可升序与降序组合排序。 ③ SQL 可以进行求平均值、求最大值、求最小值、统计个数、分类汇总等各种计算。 ④ SQL 是基于关系代数和关系运算的语言。 ⑤ 关系数据模型的存取路径对用户透明。 4、关系的运算分类：关系的运算分为集合运算（并、交、差）和专门的关系运算（选择、投影、连接）。 并、交、差的前提是两个关系的关系模式相同，也就是属性的个数和属性名相同，并且对应的属性取自相同的域。并运算记作 R∪S。 5、关系运算要点：二维表的主要运算： - 选择运算：一元运算；新关系中的元组（行）是原关系中元组的子集，结果关系的属性（列）与原关系相同。 - 投影运算：一元运算；新关系中的属性（列）是原关系属性的子集，元组（行）数量可能减少（重复行被合并）。 - 连接运算：二元运算；按两个关系的共有属性（共同属性）把它们组合起来。 传统的集合运算（二元运算）： - 特点：参加运算的两个关系要具有相同的模式（属性个数相同、对应属性的域相同）；操作的对象与结果都是关系。 - 并操作：结果为属于两个关系的所有元组，重复元组只保留一个。 6、连接操作：连接是从关系 R 和 S 的广义笛卡尔积中选取属性值之间满足某一 θ 运算的元组，记为 R⋈_{iθj}S，其中 i 表示关系 R 的第 i 个属性，j 表示关系 S 的第 j 个属性，θ 是算术比较符。连接的形式定义如下： R⋈_{iθj}S σ_{iθ(p+j)}(R×S) 即在 R 和 S 的广义笛卡尔积中挑选第 i 个属性和第 p+j 个属性满足 θ 运算的元组，其中 p 为关系 R 的属性个数。如果 θ 是等号“”，这个连接操作称为“等值连接”。 口诀：写出属性名，十字交叉确定元组，按照连接条件筛选元组。 7、并操作：并操作是二元操作，它要求参与操作的两个关系具有相同的关系模式。其作用是将两个关系组合成一个新的关系。根据集合论的定义，并操作创建的新关系中的每一个元组或者属于第一个关系，或者属于第二个关系，或者在两个关系中皆有；重复的元组只保留一个。 考向复习提示：传统集合运算 vs 专门关系代数运算 • 传统集合运算：并（∪）、交（∩）、差（-）、笛卡尔积（×，元组数相乘，属性数相加）； • 专门关系代数运算：选择（σ，横向选出满足条件的元组行）、投影（π，纵向选出指定的一组列属性并自动消除重复行）、连接（⋈，笛卡尔积后按条件筛选）、除运算（÷）。 高频易错陷阱：选择与投影动作记忆口诀 专转本单选高频陷阱题： • “选择（Selection，用符号 σ 表示）”是“横向按行切”（从表中挑选出满足 WHERE 条件的记录行）； • “投影（Projection，用符号 π 表示）”是“纵向按列切”（从表中挑选出需要的字段列，并且数学定义上必须自动去除重复出现的行）；考试常偷换横切与纵切方向！$kbsplitse$),(218, $kbsplit$[{"t":"list","id":"b6-6-1-3-b1","imp":"core","items":["1、人工智能发展历程","（1）形成阶段(1950 年代)：AI 元年是 1956 年。","（2）快速发展阶段（1970 年代）：以专家系统为代表","（3）发展中期阶段（1980 年代）：以第五代计算机为代表","（4）高速发展阶段（1988 年代及以后）：以神经网络为代表","2、==达特茅斯会议与人工智能、神经网络概念的提出==：==1956年达特茅斯会议上==，麦卡锡首次提出人工智能的概念；明斯基最早提出神经网络。","3、==人工智能发展历程阶段划分及相关概念辨析==：^^人工智能发展历程^^：","（1）^^形成阶段（20世纪50年代）^^：==AI 元年是 1956 年==。1956 年夏季，美国的一些年轻科学家在达特茅斯学院召开夏季讨论会，会上第一次提出“人工智能”这一术语。","（2）^^快速发展阶段（20世纪70年代）^^：==以专家系统为代表==。","（3）^^发展中期阶段（20世纪80年代）^^：==以第五代计算机为代表==。","（4）^^高速发展阶段（20世纪80年代及以后）^^：==以神经网络为代表==。 自然语言处理（NLP）是计算机科学领域与人工智能领域中的一个重要方向，研究能实现人与计算机之间用自然语言进行有效通信的各种理论和方法。","4、==起步发展期（20世纪50年代—60年代初）==：==人工智能概念提出后==，相继取得了一批令人瞩目的研究成果，如机器定理证明、跳棋程序等，掀起人工智能发展的第一个高潮。","- ^^1950年^^：==图灵测试==。著名的图灵测试诞生，按照“人工智能之父”艾伦·图灵的定义，如果一台机器能够与人类展开对话（通过电传设备）而不能被辨别出其机器身份，那么就称这台机器具有智能。同一年，图灵还预言了创造出具有真正智能的机器的可能性。","- ^^1954年^^：==第一台可编程机器人诞生==。美国人乔治·戴沃尔设计了世界上第一台可编程机器人。","- ^^1956年^^：==人工智能诞生==。","5、==人工智能发展历程中的标志性事件==：==1980年==，卡内基梅隆大学为数字设备公司设计了一套名为 XCON 的“专家系统”。专家系统是一种采用人工智能程序的系统。仅仅7年之后，这个曾经轰动一时的人工智能系统就宣告退出历史舞台。 到1987年时，苹果和 IBM 公司生产的台式机性能都超过了 Symbolics 等厂商生产的通用计算机。 从20世纪90年代中期开始，由于网络技术特别是互联网的发展，人工智能开始由单个智能主体的研究转向基于网络环境下的分布式人工智能研究。 1997年5月11日，IBM 开发的计算机系统“深蓝”战胜了国际象棋世界冠军卡斯帕罗夫。","6、==人工智能的起源与第一次AI寒冬==：","1）人工智能的起源（1900—1956年）：1900年数学家希尔伯特宣布了23个未解难题，其中第二个和第十个问题与人工智能密切相关，最终促进了计算机的发明；冯·诺依曼体系结构奠定了人工智能和计算机技术的基础。","2）黄金时代（1956—1974年）：1956年达特茅斯会议首次提出人工智能。","3）第一次 AI 寒冬——反思发展（1974—1980年）。","7、==人工智能发展的三次浪潮==：^^人工智能发展经历三次浪潮^^：","① ^^20世纪50年代到60年代^^：==非智能对话机器人==。","② ^^20世纪80年代到90年代^^：==语音识别==。","③ ^^21世纪初^^：==深度学习加大数据==。"],"title":"","ordered":false},{"t":"callout","id":"b6-6-1-3-b2","imp":"core","kind":"tip","text":"==1956 年夏，达特茅斯会议（Dartmouth Conference）在美国达特茅斯学院召开，麦卡锡、明斯基、罗切斯特、香农等学者正式首次提出了“Artificial Intelligence（人工智能）”这一划时代术语==；标志着人工智能作为一门独立的新兴科学正式诞生。","title":"考向复习提示：1956 年达特茅斯会议与 AI 诞生"},{"t":"callout","id":"b6-6-1-3-b3","imp":"core","kind":"trap","text":"专转本单选常考历史考点：“人工智能（AI）作为一门学科诞生的标志性历史事件是什么？”答案必须且唯一选择：==1956 年美国达特茅斯会议==！切勿与 1946 年 ENIAC 计算机诞生或 1950 年图灵发表论文相混淆！","title":"高频易错陷阱：达特茅斯会议标志着人工智能学科的正式诞生"}]$kbsplit$::jsonb, $kbsplitse$B6-6.1.3 人工智能发展历程。 1、人工智能发展历程 （1）形成阶段(1950 年代)：AI 元年是 1956 年。 （2）快速发展阶段（1970 年代）：以专家系统为代表 （3）发展中期阶段（1980 年代）：以第五代计算机为代表 （4）高速发展阶段（1988 年代及以后）：以神经网络为代表 2、达特茅斯会议与人工智能、神经网络概念的提出：1956年达特茅斯会议上，麦卡锡首次提出人工智能的概念；明斯基最早提出神经网络。 3、人工智能发展历程阶段划分及相关概念辨析：人工智能发展历程： （1）形成阶段（20世纪50年代）：AI 元年是 1956 年。1956 年夏季，美国的一些年轻科学家在达特茅斯学院召开夏季讨论会，会上第一次提出“人工智能”这一术语。 （2）快速发展阶段（20世纪70年代）：以专家系统为代表。 （3）发展中期阶段（20世纪80年代）：以第五代计算机为代表。 （4）高速发展阶段（20世纪80年代及以后）：以神经网络为代表。 自然语言处理（NLP）是计算机科学领域与人工智能领域中的一个重要方向，研究能实现人与计算机之间用自然语言进行有效通信的各种理论和方法。 4、起步发展期（20世纪50年代—60年代初）：人工智能概念提出后，相继取得了一批令人瞩目的研究成果，如机器定理证明、跳棋程序等，掀起人工智能发展的第一个高潮。 - 1950年：图灵测试。著名的图灵测试诞生，按照“人工智能之父”艾伦·图灵的定义，如果一台机器能够与人类展开对话（通过电传设备）而不能被辨别出其机器身份，那么就称这台机器具有智能。同一年，图灵还预言了创造出具有真正智能的机器的可能性。 - 1954年：第一台可编程机器人诞生。美国人乔治·戴沃尔设计了世界上第一台可编程机器人。 - 1956年：人工智能诞生。 5、人工智能发展历程中的标志性事件：1980年，卡内基梅隆大学为数字设备公司设计了一套名为 XCON 的“专家系统”。专家系统是一种采用人工智能程序的系统。仅仅7年之后，这个曾经轰动一时的人工智能系统就宣告退出历史舞台。 到1987年时，苹果和 IBM 公司生产的台式机性能都超过了 Symbolics 等厂商生产的通用计算机。 从20世纪90年代中期开始，由于网络技术特别是互联网的发展，人工智能开始由单个智能主体的研究转向基于网络环境下的分布式人工智能研究。 1997年5月11日，IBM 开发的计算机系统“深蓝”战胜了国际象棋世界冠军卡斯帕罗夫。 6、人工智能的起源与第一次AI寒冬： 1）人工智能的起源（1900—1956年）：1900年数学家希尔伯特宣布了23个未解难题，其中第二个和第十个问题与人工智能密切相关，最终促进了计算机的发明；冯·诺依曼体系结构奠定了人工智能和计算机技术的基础。 2）黄金时代（1956—1974年）：1956年达特茅斯会议首次提出人工智能。 3）第一次 AI 寒冬——反思发展（1974—1980年）。 7、人工智能发展的三次浪潮：人工智能发展经历三次浪潮： ① 20世纪50年代到60年代：非智能对话机器人。 ② 20世纪80年代到90年代：语音识别。 ③ 21世纪初：深度学习加大数据。 考向复习提示：1956 年达特茅斯会议与 AI 诞生 1956 年夏，达特茅斯会议（Dartmouth Conference）在美国达特茅斯学院召开，麦卡锡、明斯基、罗切斯特、香农等学者正式首次提出了“Artificial Intelligence（人工智能）”这一划时代术语；标志着人工智能作为一门独立的新兴科学正式诞生。 高频易错陷阱：达特茅斯会议标志着人工智能学科的正式诞生 专转本单选常考历史考点：“人工智能（AI）作为一门学科诞生的标志性历史事件是什么？”答案必须且唯一选择：1956 年美国达特茅斯会议！切勿与 1946 年 ENIAC 计算机诞生或 1950 年图灵发表论文相混淆！$kbsplitse$),(271, $kbsplit$[{"t":"list","id":"s2-1-1-b1","imp":"normal","items":["1、数据库系统"],"title":"","ordered":false},{"h":403,"t":"img","w":1062,"id":"s2-1-1-b2","imp":"normal","src":"/kb-assets/skill/p61_r0_e9eabfd371d2f3b5.png","title":""},{"t":"list","id":"s2-1-1-b3","imp":"core","items":["2、==表==","（1）表是一种有结构化的文件。","（2）表（table） ：某种特定类型数据的结构化清单。","==（3）在数据库中可以创建多个文件名，且文件名不能重复，是唯一的标识。==","==（4）模式（schema）： 关于数据库和表的布局及特性的信息==","==（5）关系可以表示为一个二维的表。==","==（6）表有记录（元组）、列（属性、码、字段）等=="],"title":"","ordered":false},{"h":312,"t":"img","w":594,"id":"s2-1-1-b4","imp":"normal","src":"/kb-assets/skill/p61_r1_70ccd35402e1758f.png","title":""},{"t":"list","id":"s2-1-1-b5","imp":"core","items":["3、==列==","（1）==表由列组成==。==列中存储着表中某部分的信息==。","（2）==列（column）是表中的一个字段。==","（3）==所有表都是由一个或多个列组成的==。","（4）==可以使用SELECT（投影）显示列。=="],"title":"","ordered":false},{"h":286,"t":"img","w":571,"id":"s2-1-1-b6","imp":"normal","src":"/kb-assets/skill/p61_r2_0bf10466fba41b1f.png","title":""},{"t":"list","id":"s2-1-1-b7","imp":"core","items":["4、==行==","==（1）行（row） 表中的一个记录==","==（2）一个表中可以有0 或多条记录。数据量越大，查询的速度就会慢，所以可以对索引的使用、使用合适的数据类型来等提升或优化查询速度。==","==（3）可以通过WHERE（选择）语句将记录筛选出来。=="],"title":"","ordered":false},{"h":378,"t":"img","w":712,"id":"s2-1-1-b8","imp":"normal","src":"/kb-assets/skill/p62_r0_2aad611d496e97b0.png","title":""},{"t":"list","id":"s2-1-1-b9","imp":"core","items":["5、==主键==","==（1）表中每一行都应该有可以唯一标识自己的一列（或一组列）==","==（2）一个表只能有一个主键。主键（主码、主关键字等）可以是一列或多列组成。==","==（3）主键使用的SQL 中primary key（大小写不区分）来定义标识。==","==（4）作用：主键实现唯一标识实体,主键实现实体完整性。==","^^（5）比如学号、教师编号、区号、产品编号等^^"],"title":"","ordered":false},{"h":273,"t":"img","w":914,"id":"s2-1-1-b10","imp":"normal","src":"/kb-assets/skill/p62_r1_03f654eed4ab8197.png","title":""},{"t":"list","id":"s2-1-1-b11","imp":"core","items":["6、==外键==","（1）==某表的一个主键,出现在另一个表中,那么这个主键在另一个表中的定义为外键（外码）。==","（2）==作用：保持数据一致性，完整性，即数据参照完整性。==","（3）==外键使用的SQL 中foreign key（大小写不区分）来定义标识。==","（4）==一个表中可以有多个外键==。","（5^^）比如成绩表中：教师编号、学号、课程号等者是成绩表的外键。^^","7、==数据类型==","==（1）数据库中每个列都有相应的数据类型。==","==（2）数据类型定义列可以存储的数据种类。==","^^（3）例如，如果列中存储的为数字（或许是订单中的物品数），则相应的数据类型应该为数值类型。如果列中存储的是日期、文本、注释、金额等，则应该用恰当的数据类型规定出来^^。","（4）数据类型（datatype） 所容许的数据的类型。","（5）==每个表列都有相应的数据类型，它限制（或容许）该列中存储的数据。=="],"title":"","ordered":false},{"h":264,"t":"img","w":611,"id":"s2-1-1-b12","imp":"normal","src":"/kb-assets/skill/p62_r2_203586485cb978ff.png","title":""},{"t":"list","id":"s2-1-1-b13","imp":"core","items":["8、==数据库设计阶段=="],"title":"","ordered":false},{"h":618,"t":"img","w":1292,"id":"s2-1-1-b14","imp":"normal","src":"/kb-assets/skill/p63_r0_057d5a5dc1696787.png","title":""},{"t":"list","id":"s2-1-1-b15","imp":"core","items":["9、==E-R 图==","（1）==E-R 图也称实体-联系图(Entity Relationship Diagram)，提供了表示实体类型、属性和联系的方法，用来描述现实世界的概念模型。==","（2）==联系的类型==：","①、==1:1（一对一）==：比如身份证信息与人之间关系，一个人只能有一个身份证信息。","②、==1:n（一对多）==：比如宿舍与学生之间关系；一个宿舍可以住多个学生居住。","③、==m:n（多对多）==：比如学生与课程之间关系；一个学生可以选择多门课，一门课可以被多个学生选择","（3）==图形表示==：","①、==矩形框==：==表示实体型，矩形框内写明实体名称==；","学生","②、==椭圆图框：表示实体的属性，并用“实心线段”将其与相应关系的“实体型”连接起来，对于主属性（主键）名，则在其名称下划一下划线。==","==主键下面有下划线==学号学生姓名","③、==菱形框：表示实体型之间的联系成因，在菱形框内写明联系名，并用”实心线段“分别与有关实体型连接起来，同时在”实心线段“旁标上联系的类型=="],"title":"","ordered":false},{"h":344,"t":"img","w":654,"id":"s2-1-1-b16","imp":"normal","src":"/kb-assets/skill/p63_r1_f5fdc4ca42fa899e.png","title":""},{"t":"list","id":"s2-1-1-b17","imp":"core","items":["（4）画E-R 图的常用软件或工具：==visio、rose、word(插入形状)==等。","10、绘制E-R 步骤","^^（1）首先要找出实体，以及实体的相应属于^^","^^（2）其次找到实体间存在的关系^^","^^（3）最后按照E-R 图模型规则来绘制^^","==11、一对一E-R 图举例==例1：两个实体集之间的一对一的联系的绘制方法。假设某学院有若干个系，每个系只有一名主任。则主任和系的属性分别如下：","主任—编号，姓名，年龄，学历系—系编号，系名主任和系之间是一个管理关系，体现主任一个任职时间。如一对一E-R 图的示。","==12、一对多E-R 图举例==例2：假设在某仓库管理系统中，有两个实体集：他库和商品。仓库用来存放商品，且规定一类商品只能存放在一个仓库中，一个仓库可以存放多件商品。","仓库和商品之间是一对多的联系。","仓库—仓库号，地点，面积联单商品—商品号，商品名，价格在存放联系中要反映出存放商品的数量。如一对多E-R 图的示。","==13、多对多E-R 图举例==例3：假设在某教务管理系统中，一个教师可以上多门课，一门课也可以由多个老师去上。教师和课程之间是多对多的联系。教师和课程可用以下属性来描述：","教师—教师号，教师名，职称课程—课程号，课程名，班级在“讲授”联系中应能反映出教师的授课程质量。如多对多E-R 图的示。"],"title":"","ordered":false},{"h":757,"t":"img","w":1282,"id":"s2-1-1-b18","imp":"normal","src":"/kb-assets/skill/p64_r0_fe5eca1586619d07.png","title":""},{"t":"list","id":"s2-1-1-b19","imp":"core","items":["==一对一E-R 图                       一对多E-R 图=="],"title":"","ordered":false},{"h":882,"t":"img","w":682,"id":"s2-1-1-b20","imp":"normal","src":"/kb-assets/skill/p65_r0_f2dac47c3a547f06.png","title":""},{"t":"list","id":"s2-1-1-b21","imp":"core","items":["==多对多E-R 图==2 创建数据库和表","14、==数据库、DBMS 与 SQL 语言基础==：数据库（Database）是长期保存在计算机存储设备上、按照一定规则组织起来、可以被各种用户或应用共享的数据集合。 数据库管理系统（DataBase Management System，DBMS）是操作和管理数据库的大型软件，用于==建立、使用和维护数据库==，并对数据库进行统一管理和控制，以保证数据库的安全性和完整性；用户通过 DBMS 访问数据库中的数据。 MySQL 即 DBMS，负责管理真实的数据库；数据库中存放数据集合，包括表、视图等；表以二维行列存储数据，行（row）在 SQL 中称为一条记录（实体），列（column）称为字段。","15、==关系数据模型的三类完整性规则==：^^关系数据模型有三类完整性规则^^：==“实体完整性”（主键不能为空值或重值）==；“引用完整性”（在关系中不允许引用不存在的实体元组）；“用户自定义完整性约束”（由应用环境对数据的需求而决定）。","16、==存储模式（内模式）与 SQL 的非过程性==：^^存储模式（内模式）^^：==数据在数据库中的内部表示==，即对数据的物理结构和存储方式的描述。 综述：应用系统的全局关系模式对应于基本表，其存储结构对应于存储文件；面向用户的局部关系模式对应于视图或部分基本表。 SQL 包含对数据库的全部操作，用 SQL 语言可实现数据库应用过程中的全部活动。使用 SQL 只需指出需要哪类数据（做什么），不必指出获得这些数据的步骤（如何做）。","17、==E-R 图的基本符号与联系类型==：==概念模型的建立方法是“实体-联系”方法==，即 E-R 图。 在 E-R 图中，矩形表示实体，椭圆表示属性，菱形表示表与表之间的联系。 E-R 概念模型中存在一对一、一对多、多对多三种联系。","18、==系统设计阶段的三级结构设计==：^^“系统设计”阶段包括^^：==概念结构设计（E-R 图）==；逻辑结构设计（即关系模式设计）；物理结构设计（包含存储结构设计和程序结构设计）。","19、==数据库控制与数据库保护==：","^^1）数据库的破坏来自四个方面^^：系统故障、多用户并发访问数据库时造成数据的不一致、人为破坏、输入数据本身是错误的（或更新时造成数据错误）。","^^2）通过四个方面来实现数据库控制（即数据库保护）^^：安全性控制、备份与恢复、完整性控制、并发控制。","^^3）安全性控制^^：保护数据以防止不合法的使用。主要技术：","①==用户标识与口令==；","②访问控制（SQL 中的 GRANT 授权语句、REVOKE 取消授权语句用于==访问授权）==；","③==审计；==","④==数据加密==；","⑤^^视图的保护。 4）备份与恢复^^：==实现技术是转储和日志==。数据库恢复的基本机制就是“冗余”，通过备份来重复存储数据库中的数据。"],"title":"","ordered":false},{"t":"callout","id":"s2-1-1-b22","imp":"core","kind":"tip","text":"E-R 图三大图元：==矩形表示实体集、椭圆形表示属性、菱形表示实体间的联系==；联系度包含 1:1、1:n 和 m:n 三种；转换规则：==一个 m:n 复合联系必须独立转换为一个单独的关系模式，其主键由两个相连实体的外键共同组成复合主键==。","title":"考向复习提示：E-R 图三大核心图元与向关系模型转换规则"},{"t":"callout","id":"s2-1-1-b23","imp":"core","kind":"trap","text":"专转本大题必考：当两个实体集之间存在 1:n 关联（如班级与学生）时，==必须将 1 端（班级）的主键作为外键添加到 n 端（学生表）中，而不是反过来把学生主键加到班级表中==！如果加反会导致班级表出现多值属性破坏关系规范化；多对多联系若漏掉将其独立建表更是扣分雷区！","title":"高频易错陷阱：E-R 图转关系模式高频丢分点"}]$kbsplit$::jsonb, $kbsplitse$S2-1.1 根据系统需求绘制 E-R 图。 1、数据库系统 2、表 （1）表是一种有结构化的文件。 （2）表（table） ：某种特定类型数据的结构化清单。 （3）在数据库中可以创建多个文件名，且文件名不能重复，是唯一的标识。 （4）模式（schema）： 关于数据库和表的布局及特性的信息 （5）关系可以表示为一个二维的表。 （6）表有记录（元组）、列（属性、码、字段）等 3、列 （1）表由列组成。列中存储着表中某部分的信息。 （2）列（column）是表中的一个字段。 （3）所有表都是由一个或多个列组成的。 （4）可以使用SELECT（投影）显示列。 4、行 （1）行（row） 表中的一个记录 （2）一个表中可以有0 或多条记录。数据量越大，查询的速度就会慢，所以可以对索引的使用、使用合适的数据类型来等提升或优化查询速度。 （3）可以通过WHERE（选择）语句将记录筛选出来。 5、主键 （1）表中每一行都应该有可以唯一标识自己的一列（或一组列） （2）一个表只能有一个主键。主键（主码、主关键字等）可以是一列或多列组成。 （3）主键使用的SQL 中primary key（大小写不区分）来定义标识。 （4）作用：主键实现唯一标识实体,主键实现实体完整性。 （5）比如学号、教师编号、区号、产品编号等 6、外键 （1）某表的一个主键,出现在另一个表中,那么这个主键在另一个表中的定义为外键（外码）。 （2）作用：保持数据一致性，完整性，即数据参照完整性。 （3）外键使用的SQL 中foreign key（大小写不区分）来定义标识。 （4）一个表中可以有多个外键。 （5）比如成绩表中：教师编号、学号、课程号等者是成绩表的外键。 7、数据类型 （1）数据库中每个列都有相应的数据类型。 （2）数据类型定义列可以存储的数据种类。 （3）例如，如果列中存储的为数字（或许是订单中的物品数），则相应的数据类型应该为数值类型。如果列中存储的是日期、文本、注释、金额等，则应该用恰当的数据类型规定出来。 （4）数据类型（datatype） 所容许的数据的类型。 （5）每个表列都有相应的数据类型，它限制（或容许）该列中存储的数据。 8、数据库设计阶段 9、E-R 图 （1）E-R 图也称实体-联系图(Entity Relationship Diagram)，提供了表示实体类型、属性和联系的方法，用来描述现实世界的概念模型。 （2）联系的类型： ①、1:1（一对一）：比如身份证信息与人之间关系，一个人只能有一个身份证信息。 ②、1:n（一对多）：比如宿舍与学生之间关系；一个宿舍可以住多个学生居住。 ③、m:n（多对多）：比如学生与课程之间关系；一个学生可以选择多门课，一门课可以被多个学生选择 （3）图形表示： ①、矩形框：表示实体型，矩形框内写明实体名称； 学生 ②、椭圆图框：表示实体的属性，并用“实心线段”将其与相应关系的“实体型”连接起来，对于主属性（主键）名，则在其名称下划一下划线。 主键下面有下划线学号学生姓名 ③、菱形框：表示实体型之间的联系成因，在菱形框内写明联系名，并用”实心线段“分别与有关实体型连接起来，同时在”实心线段“旁标上联系的类型 （4）画E-R 图的常用软件或工具：visio、rose、word(插入形状)等。 10、绘制E-R 步骤 （1）首先要找出实体，以及实体的相应属于 （2）其次找到实体间存在的关系 （3）最后按照E-R 图模型规则来绘制 11、一对一E-R 图举例例1：两个实体集之间的一对一的联系的绘制方法。假设某学院有若干个系，每个系只有一名主任。则主任和系的属性分别如下： 主任—编号，姓名，年龄，学历系—系编号，系名主任和系之间是一个管理关系，体现主任一个任职时间。如一对一E-R 图的示。 12、一对多E-R 图举例例2：假设在某仓库管理系统中，有两个实体集：他库和商品。仓库用来存放商品，且规定一类商品只能存放在一个仓库中，一个仓库可以存放多件商品。 仓库和商品之间是一对多的联系。 仓库—仓库号，地点，面积联单商品—商品号，商品名，价格在存放联系中要反映出存放商品的数量。如一对多E-R 图的示。 13、多对多E-R 图举例例3：假设在某教务管理系统中，一个教师可以上多门课，一门课也可以由多个老师去上。教师和课程之间是多对多的联系。教师和课程可用以下属性来描述： 教师—教师号，教师名，职称课程—课程号，课程名，班级在“讲授”联系中应能反映出教师的授课程质量。如多对多E-R 图的示。 一对一E-R 图 一对多E-R 图 多对多E-R 图2 创建数据库和表 14、数据库、DBMS 与 SQL 语言基础：数据库（Database）是长期保存在计算机存储设备上、按照一定规则组织起来、可以被各种用户或应用共享的数据集合。 数据库管理系统（DataBase Management System，DBMS）是操作和管理数据库的大型软件，用于建立、使用和维护数据库，并对数据库进行统一管理和控制，以保证数据库的安全性和完整性；用户通过 DBMS 访问数据库中的数据。 MySQL 即 DBMS，负责管理真实的数据库；数据库中存放数据集合，包括表、视图等；表以二维行列存储数据，行（row）在 SQL 中称为一条记录（实体），列（column）称为字段。 15、关系数据模型的三类完整性规则：关系数据模型有三类完整性规则：“实体完整性”（主键不能为空值或重值）；“引用完整性”（在关系中不允许引用不存在的实体元组）；“用户自定义完整性约束”（由应用环境对数据的需求而决定）。 16、存储模式（内模式）与 SQL 的非过程性：存储模式（内模式）：数据在数据库中的内部表示，即对数据的物理结构和存储方式的描述。 综述：应用系统的全局关系模式对应于基本表，其存储结构对应于存储文件；面向用户的局部关系模式对应于视图或部分基本表。 SQL 包含对数据库的全部操作，用 SQL 语言可实现数据库应用过程中的全部活动。使用 SQL 只需指出需要哪类数据（做什么），不必指出获得这些数据的步骤（如何做）。 17、E-R 图的基本符号与联系类型：概念模型的建立方法是“实体-联系”方法，即 E-R 图。 在 E-R 图中，矩形表示实体，椭圆表示属性，菱形表示表与表之间的联系。 E-R 概念模型中存在一对一、一对多、多对多三种联系。 18、系统设计阶段的三级结构设计：“系统设计”阶段包括：概念结构设计（E-R 图）；逻辑结构设计（即关系模式设计）；物理结构设计（包含存储结构设计和程序结构设计）。 19、数据库控制与数据库保护： 1）数据库的破坏来自四个方面：系统故障、多用户并发访问数据库时造成数据的不一致、人为破坏、输入数据本身是错误的（或更新时造成数据错误）。 2）通过四个方面来实现数据库控制（即数据库保护）：安全性控制、备份与恢复、完整性控制、并发控制。 3）安全性控制：保护数据以防止不合法的使用。主要技术： ①用户标识与口令； ②访问控制（SQL 中的 GRANT 授权语句、REVOKE 取消授权语句用于访问授权）； ③审计； ④数据加密； ⑤视图的保护。 4）备份与恢复：实现技术是转储和日志。数据库恢复的基本机制就是“冗余”，通过备份来重复存储数据库中的数据。 考向复习提示：E-R 图三大核心图元与向关系模型转换规则 E-R 图三大图元：矩形表示实体集、椭圆形表示属性、菱形表示实体间的联系；联系度包含 1:1、1:n 和 m:n 三种；转换规则：一个 m:n 复合联系必须独立转换为一个单独的关系模式，其主键由两个相连实体的外键共同组成复合主键。 高频易错陷阱：E-R 图转关系模式高频丢分点 专转本大题必考：当两个实体集之间存在 1:n 关联（如班级与学生）时，必须将 1 端（班级）的主键作为外键添加到 n 端（学生表）中，而不是反过来把学生主键加到班级表中！如果加反会导致班级表出现多值属性破坏关系规范化；多对多联系若漏掉将其独立建表更是扣分雷区！$kbsplitse$),(318, $kbsplit$[{"t":"list","id":"s5-3-1-b1","imp":"core","items":["1、==查询系统基本信息—“系统”界面=="],"title":"","ordered":false},{"h":459,"t":"img","w":1004,"id":"s5-3-1-b2","imp":"normal","src":"/kb-assets/skill/p134_r1_f879acdd848f9871.png","title":""},{"t":"list","id":"s5-3-1-b3","imp":"core","items":["2、==查询系统基本信息—dxdiag 命令=="],"title":"","ordered":false},{"h":539,"t":"img","w":1095,"id":"s5-3-1-b4","imp":"normal","src":"/kb-assets/skill/p135_r0_2efafbce3aa4ac02.png","title":""},{"t":"list","id":"s5-3-1-b5","imp":"core","items":["3、==查询系统基本信息—第三方软件（鲁大师）=="],"title":"","ordered":false},{"h":579,"t":"img","w":1019,"id":"s5-3-1-b6","imp":"normal","src":"/kb-assets/skill/p135_r1_7b8d6ebe9cbcc670.png","title":""},{"t":"list","id":"s5-3-1-b7","imp":"core","items":["4、==查询系统设备信息—设备管理器=="],"title":"","ordered":false},{"h":604,"t":"img","w":844,"id":"s5-3-1-b8","imp":"normal","src":"/kb-assets/skill/p135_r2_ffff7aa62a96d32c.png","title":""},{"t":"list","id":"s5-3-1-b9","imp":"core","items":["==5、查询系统设备信息—dxdiag 命令=="],"title":"","ordered":false},{"h":519,"t":"img","w":1016,"id":"s5-3-1-b10","imp":"normal","src":"/kb-assets/skill/p136_r0_1c458a8b2c803974.png","title":""},{"t":"list","id":"s5-3-1-b11","imp":"core","items":["==6、查询系统设备信息—第三方软件（鲁大师）==","7、==查看系统属性==：^^查看系统属性的方法^^：==在“控制面板”窗口中双击“系统”图标==，或在桌面上右击“我的电脑”图标，在弹出的快捷菜单中选择“属性”命令，同样可以打开“系统属性”对话框，在“常规”选项卡中可以看到系统信息。 由于用户的计算机配置各有不同，看到的信息也就不尽相同。在“常规”选项卡中显示了计算机系统的基本状态，包括操作系统的类型、版本及注册名等信息。","8、==硬件管理：设备管理器、驱动程序与硬件配置文件==：==如果要查看计算机硬件的相关信息==，则在“系统属性”对话框中选择“硬件”选项卡，该选项卡中有 3 种硬件管理类别：“设备管理器”、“驱动程序”和“硬件配置文件”。","（1）设备管理器 “设备管理器”为用户提供计算机中所安装硬件的图形显示。使用“设备管理器”可以检查硬件的状态并更新硬件设备的驱动程序。对计算机硬件有深入了解的高级用户也可以使用“设备管理器”的诊断功能来解决设备冲突问题并更改资源设置。 在“硬件”选项卡中单击【设备管理器】按钮，打开“设备管理器”窗口。","9、==光盘驱动器的读盘原理==：^^光盘驱动器（光驱）通过激光读出信息^^：","1）DVD 驱动器在读取单面双层 DVD 光盘时，使用 2 种不同的焦距；","2）DVD 驱动器向下兼容 CD。"],"title":"","ordered":false},{"h":629,"t":"img","w":1021,"id":"s5-3-1-b12","imp":"normal","src":"/kb-assets/skill/p136_r1_f4bdc36b9dce292f.png","title":""},{"t":"callout","id":"s5-3-1-b13","imp":"core","kind":"tip","text":"查看系统底层硬件物理配置的标准管理中枢是==设备管理器（快捷键 Win+X 选择设备管理器，或 Win+R 输入 `devmgmt.msc`）==；可以清晰查看 CPU 型号核数、显示适配器（显卡）、磁盘驱动器、网络适配器（网卡）及通用串行总线 USB 控制器的物理硬件工作状态。","title":"考向复习提示：设备管理器（devmgmt.msc）与系统硬件状态审查"},{"t":"callout","id":"s5-3-1-b14","imp":"core","kind":"trap","text":"专转本真题必考硬件排错图标含义： • ==带有“黄色感叹号（!）”==：表示系统已检测到该物理硬件，但==硬件驱动程序未安装、驱动损坏或驱动版本不兼容，导致设备无法正常工作==； • ==带有“向下黑色箭头（↓）”==：表示该硬件功能完好，但==当前处于被人为‘手动禁用（Disabled）’状态==！切勿混淆两者的故障成因！","title":"高频易错陷阱：设备管理器中黄色感叹号与向下箭头的故障含义"}]$kbsplit$::jsonb, $kbsplitse$S5-3.1 查看系统设备信息。 1、查询系统基本信息—“系统”界面 2、查询系统基本信息—dxdiag 命令 3、查询系统基本信息—第三方软件（鲁大师） 4、查询系统设备信息—设备管理器 5、查询系统设备信息—dxdiag 命令 6、查询系统设备信息—第三方软件（鲁大师） 7、查看系统属性：查看系统属性的方法：在“控制面板”窗口中双击“系统”图标，或在桌面上右击“我的电脑”图标，在弹出的快捷菜单中选择“属性”命令，同样可以打开“系统属性”对话框，在“常规”选项卡中可以看到系统信息。 由于用户的计算机配置各有不同，看到的信息也就不尽相同。在“常规”选项卡中显示了计算机系统的基本状态，包括操作系统的类型、版本及注册名等信息。 8、硬件管理：设备管理器、驱动程序与硬件配置文件：如果要查看计算机硬件的相关信息，则在“系统属性”对话框中选择“硬件”选项卡，该选项卡中有 3 种硬件管理类别：“设备管理器”、“驱动程序”和“硬件配置文件”。 （1）设备管理器 “设备管理器”为用户提供计算机中所安装硬件的图形显示。使用“设备管理器”可以检查硬件的状态并更新硬件设备的驱动程序。对计算机硬件有深入了解的高级用户也可以使用“设备管理器”的诊断功能来解决设备冲突问题并更改资源设置。 在“硬件”选项卡中单击【设备管理器】按钮，打开“设备管理器”窗口。 9、光盘驱动器的读盘原理：光盘驱动器（光驱）通过激光读出信息： 1）DVD 驱动器在读取单面双层 DVD 光盘时，使用 2 种不同的焦距； 2）DVD 驱动器向下兼容 CD。 考向复习提示：设备管理器（devmgmt.msc）与系统硬件状态审查 查看系统底层硬件物理配置的标准管理中枢是设备管理器（快捷键 Win+X 选择设备管理器，或 Win+R 输入 devmgmt.msc）；可以清晰查看 CPU 型号核数、显示适配器（显卡）、磁盘驱动器、网络适配器（网卡）及通用串行总线 USB 控制器的物理硬件工作状态。 高频易错陷阱：设备管理器中黄色感叹号与向下箭头的故障含义 专转本真题必考硬件排错图标含义： • 带有“黄色感叹号（!）”：表示系统已检测到该物理硬件，但硬件驱动程序未安装、驱动损坏或驱动版本不兼容，导致设备无法正常工作； • 带有“向下黑色箭头（↓）”：表示该硬件功能完好，但当前处于被人为‘手动禁用（Disabled）’状态！切勿混淆两者的故障成因！$kbsplitse$);
do $$
declare r record; old_rev record; v_rev integer; n integer;
begin
  select count(*) into n from _kbsplit;
  if n <> 19 then raise exception '预期 19 个节点，实际 %', n; end if;
  for r in select node_id, blocks, search_text from _kbsplit order by node_id loop
    select rev_no, html, source_ref into old_rev
      from kb_revision
     where node_id = r.node_id
       and rev_no = (select published_rev from kb_entry where node_id = r.node_id);
    if not found then raise exception 'node % 找不到已发布 revision', r.node_id; end if;
    select coalesce(max(rev_no), 0) + 1 into v_rev from kb_revision where node_id = r.node_id;
    insert into kb_revision(node_id, rev_no, blocks, html, search_text, source_ref)
    values (r.node_id, v_rev, r.blocks, old_rev.html, r.search_text, old_rev.source_ref);
    update kb_entry set published_rev = v_rev, updated_at = now() where node_id = r.node_id;
  end loop;
end $$;
commit;
